                                        title="Xóa đề thi"
                                    >
                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                                    </button>
                               </div>
                             </td>
                           </tr>
                         );
                       })
                     )}
                   </tbody>
                 </table>
               </div>
             </div>
           )}
        </div>
      )}
    </div>
  );
};

export default TeacherDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { SUBJECTS, GRADES, QuizConfig, QuestionType, Difficulty, Question, Quiz, StudentAttempt } from '../types';
import { generateQuizQuestions, MatrixInput, analyzeMatrixFromInput } from '../services/geminiService';
import { saveQuiz, getQuizzes, getAttempts, deleteQuiz, updateQuizStatus } from '../services/storageService';

// Declare types for global libraries
declare const mammoth: any;
declare const pdfjsLib: any;

const TeacherDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'create' | 'results'>('create');

  // Form State
  const [subject, setSubject] = useState(SUBJECTS[0]);
  const [grade, setGrade] = useState(GRADES[0]);
  const [lesson, setLesson] = useState('');

  const [mcCount, setMcCount] = useState(5);
  const [tfCount, setTfCount] = useState(0);
  const [saCount, setSaCount] = useState(0);

  const [recallCount, setRecallCount] = useState(3);
  const [understandCount, setUnderstandCount] = useState(2);
  const [applyCount, setApplyCount] = useState(0);

  // File state
  const [matrixFile, setMatrixFile] = useState<{
    name: string;
    type: 'image' | 'text';
    data: string; // Base64 for image, raw text for doc/pdf
    mimeType?: string; // Only for image
  } | null>(null);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false); // New state for AI analysis

  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedQuestions, setGeneratedQuestions] = useState<Question[]>([]);
  const [quizSaved, setQuizSaved] = useState(false);
  const [publishImmediately, setPublishImmediately] = useState(true);

  // Results & Viewing State
  const [attempts, setAttempts] = useState<StudentAttempt[]>([]);
  const [quizzes, setQuizzes] = useState<Quiz[]>([]);
  const [viewingQuiz, setViewingQuiz] = useState<Quiz | null>(null);

  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadData = () => {
    setAttempts(getAttempts());
    setQuizzes(getQuizzes());
  };

  useEffect(() => {
    if (activeTab === 'results') {
      loadData();
      setViewingQuiz(null); // Reset view on tab change
    }
  }, [activeTab]);

  // Function to process extracted data (image or text)
  const processMatrixData = async (data: MatrixInput, fileName: string) => {
    // 1. Set file state locally
    if (data.type === 'image') {
      setMatrixFile({ name: fileName, type: 'image', data: data.data, mimeType: data.mimeType });
    } else {
      setMatrixFile({ name: fileName, type: 'text', data: data.content });
    }

    // 2. Call AI to analyze
    setIsAnalyzing(true);
    try {
      const result = await analyzeMatrixFromInput(data);

      // 3. Auto-fill inputs
      setMcCount(result.counts[QuestionType.MULTIPLE_CHOICE]);
      setTfCount(result.counts[QuestionType.TRUE_FALSE]);
      setSaCount(result.counts[QuestionType.SHORT_ANSWER]);

      setRecallCount(result.difficulty[Difficulty.RECALL]);
      setUnderstandCount(result.difficulty[Difficulty.UNDERSTAND]);
      setApplyCount(result.difficulty[Difficulty.APPLY]);
    } catch (e) {
      console.error("Auto-fill failed", e);
      // Optional: don't alert, just let user fill manually
    } finally {
      setIsAnalyzing(false);
      setIsProcessingFile(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessingFile(true);

    try {
      // CASE 1: Image
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64String = reader.result as string;
          const matches = base64String.match(/^data:(.+);base64,(.+)$/);
          if (matches) {
            processMatrixData({ type: 'image', mimeType: matches[1], data: matches[2] }, file.name);
          } else {
            setIsProcessingFile(false);
          }
        };
        reader.readAsDataURL(file);
      } 
      // CASE 2: Word Document (.docx)
      else if (file.name.endsWith('.docx')) {
        const reader = new FileReader();
        reader.onloadend = (event) => {
          const arrayBuffer = event.target?.result as ArrayBuffer;
          mammoth.extractRawText({ arrayBuffer: arrayBuffer })
            .then((result: any) => {
              processMatrixData({ type: 'text', content: result.value }, file.name);
            })
            .catch((err: any) => {
              console.error(err);
              alert("Lỗi đọc file Word.");
              setIsProcessingFile(false);
            });
        };
        reader.readAsArrayBuffer(file);
      }
      // CASE 3: PDF (.pdf)
      else if (file.type === 'application/pdf' || file.name.endsWith('.pdf')) {
        const reader = new FileReader();
        reader.onloadend = async (event) => {
          const arrayBuffer = event.target?.result as ArrayBuffer;
          try {
            const loadingTask = pdfjsLib.getDocument(arrayBuffer);
            const pdf = await loadingTask.promise;
            let fullText = "";

            // Extract text from all pages
            for (let i = 1; i <= pdf.numPages; i++) {
                const page = await pdf.getPage(i);
                const textContent = await page.getTextContent();
                const pageText = textContent.items.map((item: any) => item.str).join(' ');
                fullText += `--- Trang ${i} ---\n${pageText}\n`;
            }
            processMatrixData({ type: 'text', content: fullText }, file.name);
          } catch (err) {
            console.error(err);
            alert("Lỗi đọc file PDF.");
            setIsProcessingFile(false);
          }
        };
        reader.readAsArrayBuffer(file);
      }
      else {
        alert("Định dạng file không hỗ trợ. Vui lòng tải ảnh, file Word (.docx) hoặc PDF.");
        setIsProcessingFile(false);
      }
    } catch (e) {
      console.error(e);
      alert("Có lỗi xảy ra khi xử lý file.");
      setIsProcessingFile(false);
    }
  };

  const clearFile = () => {
    setMatrixFile(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleGenerate = async () => {
    if (!lesson) {
      alert("Vui lòng nhập tên bài học");
      return;
    }

    const totalQ = mcCount + tfCount + saCount;

    // Logic: Nếu không có file ma trận, bắt buộc phải nhập số lượng câu hỏi > 0
    if (totalQ === 0) {
      alert(matrixFile 
        ? "Hệ thống chưa tìm thấy số lượng câu hỏi trong file hoặc file không có thông tin. Vui lòng nhập số lượng câu hỏi thủ công." 
        : "Vui lòng nhập số lượng câu hỏi để tạo đề thi.");
      return;
    }

    setIsGenerating(true);
    setQuizSaved(false); // Reset saved status on new generation
    setGeneratedQuestions([]);

    const config: QuizConfig = {
      subject,
      grade,
      lesson,
      totalQuestions: {
        [QuestionType.MULTIPLE_CHOICE]: mcCount,
        [QuestionType.TRUE_FALSE]: tfCount,
        [QuestionType.SHORT_ANSWER]: saCount,
      },
      difficultyDistribution: {
        [Difficulty.RECALL]: recallCount,
        [Difficulty.UNDERSTAND]: understandCount,
        [Difficulty.APPLY]: applyCount,
      }
    };

    try {
      let matrixInput: MatrixInput | undefined = undefined;

      if (matrixFile) {
        if (matrixFile.type === 'image' && matrixFile.mimeType) {
          matrixInput = { type: 'image', data: matrixFile.data, mimeType: matrixFile.mimeType };
        } else if (matrixFile.type === 'text') {
          matrixInput = { type: 'text', content: matrixFile.data };
        }
      }

      const questions = await generateQuizQuestions(config, matrixInput);

      if (questions && questions.length > 0) {
          setGeneratedQuestions(questions);
          // Auto scroll to preview on mobile
          setTimeout(() => {
            previewRef.current?.scrollIntoView({ behavior: 'smooth' });
          }, 100);
      } else {
          alert("AI không trả về câu hỏi nào. Vui lòng thử lại với cấu hình khác.");
      }
    } catch (error) {
      alert((error as Error).message);
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePublish = () => {
    if (generatedQuestions.length === 0) return;

    const newQuiz: Quiz = {
      id: `quiz_${Date.now()}`,
      title: `${subject} - ${grade} - ${lesson}`,
      config: {
        subject, grade, lesson,
        totalQuestions: {
            [QuestionType.MULTIPLE_CHOICE]: mcCount,
            [QuestionType.TRUE_FALSE]: tfCount,
            [QuestionType.SHORT_ANSWER]: saCount,
        },
        difficultyDistribution: {
            [Difficulty.RECALL]: recallCount,
            [Difficulty.UNDERSTAND]: understandCount,
            [Difficulty.APPLY]: applyCount,
        }
      },
      questions: generatedQuestions,
      createdAt: Date.now(),
      isActive: publishImmediately,
    };

    saveQuiz(newQuiz);
    setQuizSaved(true);
    alert(publishImmediately 
      ? "Đề thi đã được phát hành! Học sinh có thể làm bài ngay." 
      : "Đề thi đã được lưu nháp. Vào tab 'Quản lý' để phát hành khi cần.");
  };

  const handleDeleteQuiz = (id: string) => {
    if (confirm("Bạn có chắc chắn muốn xóa đề thi này không? Dữ liệu không thể khôi phục.")) {
        deleteQuiz(id);
        loadData(); // Reload list
        if (viewingQuiz?.id === id) setViewingQuiz(null);
    }
  };

  const handleToggleStatus = (id: string, currentStatus: boolean) => {
    updateQuizStatus(id, !currentStatus);
    loadData(); // Reload list
    // If viewing this quiz, update local view state too
    if (viewingQuiz && viewingQuiz.id === id) {
        setViewingQuiz({...viewingQuiz, isActive: !currentStatus});
    }
  };

  const clean = (str: string) => str.replace(/<[^>]*>?/gm, '');

  const handleExportWord = (title: string, questionsData: Question[]) => {
    // 1. Header Section
    const headerContent = `
      <div style="font-family: 'Times New Roman', serif;">
        <table style="width: 100%; border: none; margin-bottom: 20px;">
          <tr>
            <td style="text-align: center; vertical-align: top; width: 40%;">
              <p style="margin: 0; font-size: 11pt; font-weight: bold;">TRƯỜNG THPT LỘC BÌNH</p>
              <p style="margin: 0; font-weight: bold; text-decoration: underline;">ĐỀ CHÍNH THỨC</p>
            </td>
            <td style="text-align: center; vertical-align: top;">
              <p style="margin: 0; font-weight: bold; font-size: 13pt; text-transform: uppercase;">ĐỀ KIỂM TRA MÔN: ${subject.toUpperCase()}</p>
              <p style="margin: 0; font-size: 12pt;">Bài: ${lesson} - Lớp: ${grade}</p>
              <p style="margin: 0; font-size: 12pt; font-style: italic;">Thời gian làm bài: 45 phút</p>
            </td>
          </tr>
        </table>
      </div>
    `;

    // 2. Exam Content
    let examContent = `<div style="font-family: 'Times New Roman', serif; font-size: 13pt;">`;

    // Sort: MC -> TF -> SA
    const sortedQuestions = [...questionsData].sort((a, b) => {
        const typeOrder = { [QuestionType.MULTIPLE_CHOICE]: 1, [QuestionType.TRUE_FALSE]: 2, [QuestionType.SHORT_ANSWER]: 3 };
        return typeOrder[a.type] - typeOrder[b.type];
    });

    const hasMC = sortedQuestions.some(q => q.type === QuestionType.MULTIPLE_CHOICE);
    const hasOther = sortedQuestions.some(q => q.type !== QuestionType.MULTIPLE_CHOICE);

    if (hasMC) examContent += `<p style="font-weight: bold;">A. PHẦN TRẮC NGHIỆM</p>`;

    sortedQuestions.forEach((q, idx) => {
      // If switching from MC to Other, add header
      if (hasMC && hasOther && q.type !== QuestionType.MULTIPLE_CHOICE && sortedQuestions[idx-1]?.type === QuestionType.MULTIPLE_CHOICE) {
          examContent += `<p style="font-weight: bold; margin-top: 15px;">B. PHẦN TỰ LUẬN / ĐÚNG SAI</p>`;
      }

      examContent += `<div style="margin-bottom: 10px;">`;
      examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;

      if (q.type === QuestionType.MULTIPLE_CHOICE && q.options) {
        examContent += `<table style="width: 100%; margin-top: 5px; margin-left: 20px;"><tr>`;
        q.options.forEach((opt, i) => {
          const letter = String.fromCharCode(65 + i);
          if (i > 0 && i % 2 === 0) examContent += `</tr><tr>`;
          examContent += `<td style="padding: 2px 10px;"><strong>${letter}.</strong> ${clean(opt)}</td>`;
        });
        examContent += `</tr></table>`;
      } else if (q.type === QuestionType.SHORT_ANSWER) {
         examContent += `<p style="margin-left: 20px; margin-top: 5px;">......................................................................................................................................................</p>`;
      } else if (q.type === QuestionType.TRUE_FALSE) {
         examContent += `<p style="margin-left: 20px; margin-top: 5px;">(Đúng / Sai)</p>`;
      }
      examContent += `</div>`;
    });
    examContent += `</div>`;

    const fullContent = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
      <head>
        <meta charset='utf-8'>
        <title>${title}</title>
      </head>
      <body>
        ${headerContent}
        ${examContent}
      </body>
      </html>
    `;

    downloadDoc(fullContent, `De_Thi_${subject}_${grade}_${Date.now()}.doc`);
  };

  const handleExportAnswerKey = (title: string, questionsData: Question[]) => {
    // Sort: MC -> TF -> SA
    const sortedQuestions = [...questionsData].sort((a, b) => {
        const typeOrder = { [QuestionType.MULTIPLE_CHOICE]: 1, [QuestionType.TRUE_FALSE]: 2, [QuestionType.SHORT_ANSWER]: 3 };
        return typeOrder[a.type] - typeOrder[b.type];
    });

    let keyContent = `
      <div style="font-family: 'Times New Roman', serif; font-size: 13pt;">
      <h3 style="text-align: center; text-transform: uppercase;">HƯỚNG DẪN CHẤM & ĐÁP ÁN</h3>
      <p style="text-align: center; font-weight: bold; margin-bottom: 20px;">Môn: ${subject} - ${grade}</p>
    `;

    // Table for MCQs
    const mcqs = sortedQuestions.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
    if (mcqs.length > 0) {
        keyContent += `<p style="font-weight: bold; margin-top: 10px;">I. TRẮC NGHIỆM</p>`;
        keyContent += `<table border="1" style="border-collapse: collapse; width: 100%; text-align: center; font-size: 11pt; margin-bottom: 20px;">`;

        const cols = 10;
        let currentRow = "<tr>";
        let count = 0;

        mcqs.forEach((q, idx) => {
             let letter = "?";
             if (q.options) {
                 const matchIdx = q.options.findIndex(o => o.trim() === q.correctAnswer.trim());
                 if (matchIdx !== -1) letter = String.fromCharCode(65 + matchIdx);
                 else {
                     const fuzzyIdx = q.options.findIndex(o => q.correctAnswer.includes(o) || o.includes(q.correctAnswer));
                     if (fuzzyIdx !== -1) letter = String.fromCharCode(65 + fuzzyIdx);
                 }
             }

             const realIdx = sortedQuestions.indexOf(q) + 1;

             currentRow += `<td style="padding: 5px;">${realIdx}.${letter}</td>`;
             count++;
             if (count === cols) {
                 currentRow += "</tr>";
                 keyContent += currentRow;
                 currentRow = "<tr>";
                 count = 0;
             }
        });

        if (count > 0) {
            while (count < cols) {
                currentRow += "<td></td>";
                count++;
            }
            currentRow += "</tr>";
            keyContent += currentRow;
        }
        keyContent += `</table>`;
    }

    // Table for Others
    const others = sortedQuestions.filter(q => q.type !== QuestionType.MULTIPLE_CHOICE);
    if (others.length > 0) {
        keyContent += `<p style="font-weight: bold; margin-top: 10px;">II. TỰ LUẬN / ĐÚNG SAI</p>`;
        keyContent += `<table border="1" style="border-collapse: collapse; width: 100%; font-size: 12pt;">`;
        keyContent += `<tr style="background-color: #eee; text-align: center;">
            <th style="padding: 5px; width: 10%;">Câu</th>
            <th style="padding: 5px;">Nội dung / Đáp án</th>
            <th style="padding: 5px; width: 15%;">Điểm</th>
        </tr>`;

        others.forEach(q => {
            const realIdx = sortedQuestions.indexOf(q) + 1;
            keyContent += `<tr>
                <td style="text-align: center; font-weight: bold; vertical-align: top; padding: 5px;">${realIdx}</td>
                <td style="padding: 5px; vertical-align: top;">
                    <p style="margin: 0 0 5px 0;"><strong>Đáp án:</strong> ${clean(q.correctAnswer)}</p>
                    <p style="margin: 0;"><em>${clean(q.explanation || '')}</em></p>
                </td>
                <td style="text-align: center; vertical-align: middle;">...</td>
            </tr>`;
        });
        keyContent += `</table>`;
    }

    keyContent += `</div>`;

    const fullContent = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
      <head>
        <meta charset='utf-8'>
        <title>${title} - Đáp án</title>
      </head>
      <body>${keyContent}</body>
      </html>
    `;

    downloadDoc(fullContent, `Dap_An_${subject}_${grade}_${Date.now()}.doc`);
  };

  const downloadDoc = (content: string, filename: string) => {
    const blob = new Blob(['\ufeff', content], {
      type: 'application/msword'
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadExcel = () => {
    const dataToExport = viewingQuiz 
      ? attempts.filter(a => a.quizId === viewingQuiz.id)
      : attempts;

    if (dataToExport.length === 0) {
      alert("Chưa có dữ liệu bài làm nào.");
      return;
    }

    const headers = ["Mã đề", "Tên đề thi", "Tên học sinh", "Lớp", "Điểm số", "Thời gian nộp"];
    const rows = dataToExport.map(a => {
        const quizTitle = quizzes.find(q => q.id === a.quizId)?.title || a.quizId;
        return [
            `"${a.quizId}"`,
            `"${quizTitle}"`, 
            `"${a.studentName}"`, 
            `"${a.studentClass}"`, 
            `${a.score}/${a.totalScore}`, 
            `"${new Date(a.timestamp).toLocaleString()}"`
        ].join(",");
    });

    const csvContent = "data:text/csv;charset=utf-8," + "\uFEFF" + [headers.join(","), ...rows].join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", viewingQuiz ? `ket_qua_${viewingQuiz.title}.csv` : "tat_ca_ket_qua.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Helper to render question list
  const renderQuestionList = (questions: Question[]) => (
    <div className="space-y-6">
      {questions.map((q, idx) => (
        <div key={q.id} className="p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex justify-between items-start mb-2">
            <span className="font-bold text-blue-800">Câu {idx + 1} ({q.type === QuestionType.MULTIPLE_CHOICE ? 'TN' : q.type === QuestionType.TRUE_FALSE ? 'Đ/S' : 'TLN'})</span>
            <span className={`text-xs px-2 py-1 rounded ${q.difficulty === Difficulty.RECALL ? 'bg-green-100 text-green-800' : q.difficulty === Difficulty.UNDERSTAND ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800'}`}>
              {q.difficulty === Difficulty.RECALL ? 'Nhận biết' : q.difficulty === Difficulty.UNDERSTAND ? 'Thông hiểu' : 'Vận dụng'}
            </span>
          </div>
          <p className="mb-3 text-gray-800 font-medium">{q.text}</p>

          {q.type === QuestionType.MULTIPLE_CHOICE && q.options && (
            <div className="grid grid-cols-1 gap-2 ml-4">
              {q.options.map((opt, i) => {
                const isCorrect = opt === q.correctAnswer;
                return (
                  <div key={i} className={`p-2 rounded border ${isCorrect ? 'bg-green-50 border-green-300' : 'bg-white border-gray-200'}`}>
                    <span className={`font-semibold mr-2 ${isCorrect ? 'underline decoration-2 decoration-green-600 text-green-700 font-bold' : ''}`}>
                      {String.fromCharCode(65 + i)}.
                    </span> 
                    {opt}
                  </div>
                );
              })}
              {q.explanation && (
                <div className="mt-2 p-3 bg-blue-50 border border-blue-100 rounded text-sm text-blue-900">
                  <span className="font-bold text-blue-700">Lời giải: </span>{q.explanation}
                </div>
              )}
            </div>
          )}

          {q.type === QuestionType.TRUE_FALSE && (
              <div className="ml-4 space-y-3">
                <div className="flex gap-4">
                    <span className={`px-3 py-1 rounded border ${q.correctAnswer === 'Đúng' ? 'bg-green-50 border-green-300 font-bold' : ''}`}>Đúng</span>
                    <span className={`px-3 py-1 rounded border ${q.correctAnswer === 'Sai' ? 'bg-green-50 border-green-300 font-bold' : ''}`}>Sai</span>
                </div>
                {q.explanation && (
                    <div className="mt-2 p-3 bg-blue-50 border border-blue-100 rounded text-sm text-blue-900">
                        <span className="font-bold text-blue-700">Giải thích: </span>{q.explanation}
                    </div>
                )}
              </div>
          )}

          {q.type === QuestionType.SHORT_ANSWER && (
            <div className="ml-4 space-y-2">
                <div className="p-2 bg-yellow-50 border border-yellow-200 rounded text-yellow-800">
                <strong>Đáp án mẫu:</strong> {q.correctAnswer}
                </div>
                {q.explanation && (
                    <div className="p-3 bg-blue-50 border border-blue-100 rounded text-sm text-blue-900">
                        <span className="font-bold text-blue-700">Gợi ý/Giải thích: </span>{q.explanation}
                    </div>
                )}
            </div>
          )}
        </div>
      ))}
    </div>
  );

  const inputClass = "w-full rounded-md shadow-sm p-1.5 text-sm border border-blue-400 bg-blue-50 text-blue-900 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 font-medium placeholder-blue-400";
  const numberInputClass = "w-full mt-0.5 p-1.5 rounded-md text-sm border border-blue-400 bg-blue-50 text-blue-900 focus:ring-blue-500 font-bold text-center disabled:opacity-50";

  return (
