                                    >
                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg>
                                    </button>
                                    <button 
                                        onClick={() => handleDeleteQuiz(quiz.id)}
                                        className="text-red-500 hover:bg-red-100 p-2 rounded transition"
                                        title="Xóa đề thi"
                                    >
                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                                    </button>
                               </div>
                             </td>
                           </tr>
                         );
                       })
                     )}
                   </tbody>
                 </table>
               </div>
             </div>
           )}
        </div>
      )}
    </div>
  );
};

export default TeacherDashboard;

import { GoogleGenAI, Type } from "@google/genai";
import { QuizConfig, QuestionType, Difficulty, Question } from '../types';

const getClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

// Update type definition for matrix input to support both text (from docx/pdf) and image
export type MatrixInput = 
  | { type: 'image'; data: string; mimeType: string }
  | { type: 'text'; content: string };

export interface AnalyzedMatrix {
  counts: {
    [QuestionType.MULTIPLE_CHOICE]: number;
    [QuestionType.TRUE_FALSE]: number;
    [QuestionType.SHORT_ANSWER]: number;
  };
  difficulty: {
    [Difficulty.RECALL]: number;
    [Difficulty.UNDERSTAND]: number;
    [Difficulty.APPLY]: number;
  };
}

export const analyzeMatrixFromInput = async (matrixInput: MatrixInput): Promise<AnalyzedMatrix> => {
  const ai = getClient();
  const parts: any[] = [];

  const promptText = `
    Bạn là một trợ lý AI hỗ trợ giáo viên.
    Nhiệm vụ: Phân tích nội dung Ma trận đề thi / Bản đặc tả đề thi được cung cấp (dưới dạng hình ảnh hoặc văn bản).

    Hãy trích xuất chính xác các thông tin sau:
    1. Tổng số câu hỏi Trắc nghiệm (nhiều lựa chọn).
    2. Tổng số câu hỏi Đúng/Sai.
    3. Tổng số câu hỏi Trả lời ngắn / Tự luận.
    4. Phân phối số lượng câu hỏi theo mức độ: Nhận biết, Thông hiểu, Vận dụng (và Vận dụng cao - gộp chung vào Vận dụng).

    Nếu tài liệu không ghi rõ số lượng cụ thể mà chỉ ghi tổng điểm hoặc phần trăm, hãy ước lượng số câu tương ứng một cách hợp lý nhất (ví dụ: trắc nghiệm thường 0.25đ/câu).
    Nếu không tìm thấy thông tin nào, hãy trả về 0 cho trường đó.
  `;

  parts.push({ text: promptText });

  if (matrixInput.type === 'text') {
    parts.push({ text: `\n--- NỘI DUNG TÀI LIỆU ---\n${matrixInput.content}\n` });
  } else {
    parts.push({ inlineData: { mimeType: matrixInput.mimeType, data: matrixInput.data } });
  }

  const schema = {
    type: Type.OBJECT,
    properties: {
      counts: {
        type: Type.OBJECT,
        properties: {
          [QuestionType.MULTIPLE_CHOICE]: { type: Type.INTEGER },
          [QuestionType.TRUE_FALSE]: { type: Type.INTEGER },
          [QuestionType.SHORT_ANSWER]: { type: Type.INTEGER },
        },
        required: [QuestionType.MULTIPLE_CHOICE, QuestionType.TRUE_FALSE, QuestionType.SHORT_ANSWER]
      },
      difficulty: {
        type: Type.OBJECT,
        properties: {
          [Difficulty.RECALL]: { type: Type.INTEGER },
          [Difficulty.UNDERSTAND]: { type: Type.INTEGER },
          [Difficulty.APPLY]: { type: Type.INTEGER },
        },
        required: [Difficulty.RECALL, Difficulty.UNDERSTAND, Difficulty.APPLY]
      }
    },
    required: ["counts", "difficulty"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.1 // Low temperature for extraction accuracy
      }
    });

    const text = response.text;
    if (!text) throw new Error("AI không trả về kết quả phân tích.");

    return JSON.parse(text) as AnalyzedMatrix;
  } catch (error) {
    console.error("Error analyzing matrix:", error);
    // Return default zero structure on error to prevent app crash
    return {
      counts: { MULTIPLE_CHOICE: 0, TRUE_FALSE: 0, SHORT_ANSWER: 0 },
      difficulty: { RECALL: 0, UNDERSTAND: 0, APPLY: 0 }
    };
  }
};

export const generateQuizQuestions = async (
  config: QuizConfig, 
  matrixInput?: MatrixInput
): Promise<Question[]> => {
  const ai = getClient();

  let promptText = "";
  let parts: any[] = [];

  // Base instruction based on whether we have a matrix or not
  if (matrixInput) {
    promptText = `
    PHÂN TÍCH MA TRẬN / ĐẶC TẢ ĐỀ THI ĐƯỢC CUNG CẤP DƯỚI ĐÂY.
    Hãy đóng vai trò là giáo viên chuyên nghiệp, dựa vào nội dung ma trận/đặc tả để tạo đề thi.

    Ưu tiên tuyệt đối cấu trúc, nội dung kiến thức và phân bổ câu hỏi theo nội dung đặc tả đã cung cấp.
    Sử dụng các thông tin cấu hình dưới đây làm bổ trợ (chỉ dùng nếu đặc tả không quy định cụ thể):
    `;

    // If Text input (DOCX/PDF extracted text)
    if (matrixInput.type === 'text') {
        promptText += `\n--- NỘI DUNG ĐẶC TẢ/MA TRẬN ---\n${matrixInput.content}\n------------------------------\n`;
    }
  } else {
    promptText = `
    Đóng vai trò là một giáo viên chuyên nghiệp. Hãy tạo một đề thi trắc nghiệm theo yêu cầu sau.
    `;
  }

  promptText += `
    Thông tin môn học:
    - Môn: "${config.subject}"
    - Khối lớp: "${config.grade}"
    - Bài học: "${config.lesson}"

    Số lượng câu hỏi yêu cầu (Tham khảo, ưu tiên theo ma trận nếu có):
    - Trắc nghiệm (4 lựa chọn): ${config.totalQuestions[QuestionType.MULTIPLE_CHOICE]} câu.
    - Đúng/Sai: ${config.totalQuestions[QuestionType.TRUE_FALSE]} câu.
    - Trả lời ngắn: ${config.totalQuestions[QuestionType.SHORT_ANSWER]} câu.

    Phân phối độ khó (Tham khảo):
    - Nhận biết: ${config.difficultyDistribution[Difficulty.RECALL]}
    - Thông hiểu: ${config.difficultyDistribution[Difficulty.UNDERSTAND]}
    - Vận dụng: ${config.difficultyDistribution[Difficulty.APPLY]}

    QUAN TRỌNG - QUY ĐỊNH VỀ ĐỊNH DẠNG JSON TRẢ VỀ:
    1. Trường 'type' phải dùng chính xác: "${QuestionType.MULTIPLE_CHOICE}", "${QuestionType.TRUE_FALSE}", hoặc "${QuestionType.SHORT_ANSWER}".
    2. Trường 'difficulty' phải dùng chính xác: "${Difficulty.RECALL}", "${Difficulty.UNDERSTAND}", hoặc "${Difficulty.APPLY}".

    QUY ĐỊNH VỀ NỘI DUNG CÂU HỎI (THEO CHƯƠNG TRÌNH MỚI 2018):
    1. **Với Trắc nghiệm (${QuestionType.MULTIPLE_CHOICE})**:
       - 'text': Nội dung câu hỏi.
       - 'options': Mảng chứa 4 đáp án (A, B, C, D).
       - 'correctAnswer': Nội dung của đáp án đúng.

    2. **Với Đúng/Sai (${QuestionType.TRUE_FALSE})**:
       - 'text': Nội dung câu dẫn (ví dụ: "Cho hàm số f(x)... Xét các mệnh đề sau:").
       - 'options': **BẮT BUỘC** phải là mảng chứa **4 mệnh đề** con (a, b, c, d) liên quan đến câu dẫn.
       - 'correctAnswer': Chuỗi chứa 4 đáp án Đúng hoặc Sai tương ứng với 4 mệnh đề, ngăn cách bởi dấu phẩy (Ví dụ: "Đúng, Sai, Sai, Đúng").

    3. **Với Trả lời ngắn (${QuestionType.SHORT_ANSWER})**:
       - 'text': Nội dung câu hỏi.
       - 'correctAnswer': Đáp án ngắn gọn (số hoặc từ ngữ).
       - 'options': Để mảng rỗng [].

    4. Trường 'explanation': Bắt buộc phải có lời giải thích ngắn gọn tại sao đáp án đó đúng cho mỗi câu hỏi (với câu Đúng/Sai hãy giải thích vắn tắt từng ý).
    5. Trả về JSON object root chứa mảng 'questions'.
  `;

  // Define schema
  const schema = {
    type: Type.OBJECT,
    properties: {
      questions: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            text: { type: Type.STRING, description: "Nội dung câu hỏi hoặc câu dẫn" },
            type: { 
              type: Type.STRING, 
              enum: [QuestionType.MULTIPLE_CHOICE, QuestionType.TRUE_FALSE, QuestionType.SHORT_ANSWER],
              description: "Loại câu hỏi"
            },
            options: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "Danh sách 4 lựa chọn (TN) hoặc 4 mệnh đề (Đúng/Sai)"
            },
            correctAnswer: { type: Type.STRING, description: "Đáp án đúng (Với Đ/S là chuỗi 'Đúng, Sai, ...')" },
            explanation: { type: Type.STRING, description: "Lời giải thích hoặc hướng dẫn giải" },
            difficulty: {
              type: Type.STRING,
              enum: [Difficulty.RECALL, Difficulty.UNDERSTAND, Difficulty.APPLY],
              description: "Độ khó"
            }
          },
          required: ["text", "type", "correctAnswer", "difficulty", "explanation"],
        }
      }
    }
  };

  try {
    // Construct prompt parts
    parts.push({ text: promptText });

    // If Image input, add inlineData
    if (matrixInput && matrixInput.type === 'image') {
        parts.push({ inlineData: { mimeType: matrixInput.mimeType, data: matrixInput.data } });
    }

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.4
      }
    });

    const rawText = response.text;

    if (!rawText) {
      throw new Error("AI trả về dữ liệu rỗng.");
    }

    let jsonString = rawText;
    const firstBrace = rawText.indexOf('{');
    const lastBrace = rawText.lastIndexOf('}');

    if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
        jsonString = rawText.substring(firstBrace, lastBrace + 1);
    }

    let parsedData;
    try {
        parsedData = JSON.parse(jsonString);
    } catch (e) {
        const cleanText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
        parsedData = JSON.parse(cleanText);
    }

    const questionsArray = parsedData.questions || parsedData;

    if (!Array.isArray(questionsArray)) {
        throw new Error("Cấu trúc dữ liệu trả về không phải là danh sách câu hỏi.");
    }

    return questionsArray.map((q: any, index: number) => ({
      id: `q_${Date.now()}_${index}`,
      text: q.text || "Câu hỏi lỗi",
      type: q.type,
      options: Array.isArray(q.options) ? q.options : [],
      correctAnswer: q.correctAnswer || "",
      difficulty: q.difficulty,
      explanation: q.explanation || "Chưa có lời giải chi tiết."
    }));

  } catch (error) {
    console.error("Error generating quiz:", error);
    throw new Error("Lỗi khi tạo câu hỏi: " + (error instanceof Error ? error.message : "Lỗi không xác định"));
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { SUBJECTS, GRADES, QuizConfig, QuestionType, Difficulty, Question, Quiz, StudentAttempt } from '../types';
import { generateQuizQuestions, MatrixInput, analyzeMatrixFromInput } from '../services/geminiService';
import { saveQuiz, getQuizzes, getAttempts, deleteQuiz, updateQuizStatus } from '../services/storageService';

// Declare types for global libraries
declare const mammoth: any;
declare const pdfjsLib: any;

const TeacherDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'create' | 'results'>('create');

  // Form State
  const [subject, setSubject] = useState(SUBJECTS[0]);
  const [grade, setGrade] = useState(GRADES[0]);
  const [lesson, setLesson] = useState('');

  const [mcCount, setMcCount] = useState(5);
  const [tfCount, setTfCount] = useState(0);
  const [saCount, setSaCount] = useState(0);

  const [recallCount, setRecallCount] = useState(3);
  const [understandCount, setUnderstandCount] = useState(2);
  const [applyCount, setApplyCount] = useState(0);

  // File state
  const [matrixFile, setMatrixFile] = useState<{
    name: string;
    type: 'image' | 'text';
    data: string; // Base64 for image, raw text for doc/pdf
    mimeType?: string; // Only for image
  } | null>(null);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false); // New state for AI analysis

  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedQuestions, setGeneratedQuestions] = useState<Question[]>([]);
  const [quizSaved, setQuizSaved] = useState(false);
  const [publishImmediately, setPublishImmediately] = useState(true);

  // Results & Viewing State
  const [attempts, setAttempts] = useState<StudentAttempt[]>([]);
  const [quizzes, setQuizzes] = useState<Quiz[]>([]);
  const [viewingQuiz, setViewingQuiz] = useState<Quiz | null>(null);

  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadData = () => {
    setAttempts(getAttempts());
    setQuizzes(getQuizzes());
  };

  useEffect(() => {
    if (activeTab === 'results') {
      loadData();
      setViewingQuiz(null); // Reset view on tab change
    }
  }, [activeTab]);

  // Function to process extracted data (image or text)
  const processMatrixData = async (data: MatrixInput, fileName: string) => {
    // 1. Set file state locally
    if (data.type === 'image') {
      setMatrixFile({ name: fileName, type: 'image', data: data.data, mimeType: data.mimeType });
    } else {
      setMatrixFile({ name: fileName, type: 'text', data: data.content });
    }

    // 2. Call AI to analyze
    setIsAnalyzing(true);
    try {
      const result = await analyzeMatrixFromInput(data);

      // 3. Auto-fill inputs
      setMcCount(result.counts[QuestionType.MULTIPLE_CHOICE]);
      setTfCount(result.counts[QuestionType.TRUE_FALSE]);
      setSaCount(result.counts[QuestionType.SHORT_ANSWER]);

      setRecallCount(result.difficulty[Difficulty.RECALL]);
      setUnderstandCount(result.difficulty[Difficulty.UNDERSTAND]);
      setApplyCount(result.difficulty[Difficulty.APPLY]);
    } catch (e) {
      console.error("Auto-fill failed", e);
      // Optional: don't alert, just let user fill manually
    } finally {
      setIsAnalyzing(false);
      setIsProcessingFile(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessingFile(true);

    try {
      // CASE 1: Image
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64String = reader.result as string;
          const matches = base64String.match(/^data:(.+);base64,(.+)$/);
          if (matches) {
            processMatrixData({ type: 'image', mimeType: matches[1], data: matches[2] }, file.name);
          } else {
            setIsProcessingFile(false);
          }
        };
        reader.readAsDataURL(file);
      } 
      // CASE 2: Word Document (.docx)
      else if (file.name.endsWith('.docx')) {
        const reader = new FileReader();
        reader.onloadend = (event) => {
          const arrayBuffer = event.target?.result as ArrayBuffer;
          mammoth.extractRawText({ arrayBuffer: arrayBuffer })
            .then((result: any) => {
              processMatrixData({ type: 'text', content: result.value }, file.name);
            })
            .catch((err: any) => {
              console.error(err);
              alert("Lỗi đọc file Word.");
              setIsProcessingFile(false);
            });
        };
        reader.readAsArrayBuffer(file);
      }
      // CASE 3: PDF (.pdf)
      else if (file.type === 'application/pdf' || file.name.endsWith('.pdf')) {
        const reader = new FileReader();
        reader.onloadend = async (event) => {
          const arrayBuffer = event.target?.result as ArrayBuffer;
          try {
            const loadingTask = pdfjsLib.getDocument(arrayBuffer);
            const pdf = await loadingTask.promise;
            let fullText = "";

            // Extract text from all pages
            for (let i = 1; i <= pdf.numPages; i++) {
                const page = await pdf.getPage(i);
                const textContent = await page.getTextContent();
                const pageText = textContent.items.map((item: any) => item.str).join(' ');
                fullText += `--- Trang ${i} ---\n${pageText}\n`;
            }
            processMatrixData({ type: 'text', content: fullText }, file.name);
          } catch (err) {
            console.error(err);
            alert("Lỗi đọc file PDF.");
            setIsProcessingFile(false);
          }
        };
        reader.readAsArrayBuffer(file);
      }
      else {
        alert("Định dạng file không hỗ trợ. Vui lòng tải ảnh, file Word (.docx) hoặc PDF.");
        setIsProcessingFile(false);
      }
    } catch (e) {
      console.error(e);
      alert("Có lỗi xảy ra khi xử lý file.");
      setIsProcessingFile(false);
    }
  };

  const clearFile = () => {
    setMatrixFile(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleGenerate = async () => {
    if (!lesson) {
      alert("Vui lòng nhập tên bài học");
      return;
    }

    const totalQ = mcCount + tfCount + saCount;

    // Logic: Nếu không có file ma trận, bắt buộc phải nhập số lượng câu hỏi > 0
    if (totalQ === 0) {
      alert(matrixFile 
        ? "Hệ thống chưa tìm thấy số lượng câu hỏi trong file hoặc file không có thông tin. Vui lòng nhập số lượng câu hỏi thủ công." 
        : "Vui lòng nhập số lượng câu hỏi để tạo đề thi.");
      return;
    }

    setIsGenerating(true);
    setQuizSaved(false); // Reset saved status on new generation
    setGeneratedQuestions([]);

    const config: QuizConfig = {
      subject,
      grade,
      lesson,
      totalQuestions: {
        [QuestionType.MULTIPLE_CHOICE]: mcCount,
        [QuestionType.TRUE_FALSE]: tfCount,
        [QuestionType.SHORT_ANSWER]: saCount,
      },
      difficultyDistribution: {
        [Difficulty.RECALL]: recallCount,
        [Difficulty.UNDERSTAND]: understandCount,
        [Difficulty.APPLY]: applyCount,
      }
    };

    try {
      let matrixInput: MatrixInput | undefined = undefined;

      if (matrixFile) {
        if (matrixFile.type === 'image' && matrixFile.mimeType) {
          matrixInput = { type: 'image', data: matrixFile.data, mimeType: matrixFile.mimeType };
        } else if (matrixFile.type === 'text') {
          matrixInput = { type: 'text', content: matrixFile.data };
        }
      }

      const questions = await generateQuizQuestions(config, matrixInput);

      if (questions && questions.length > 0) {
          setGeneratedQuestions(questions);
          // Auto scroll to preview on mobile
          setTimeout(() => {
            previewRef.current?.scrollIntoView({ behavior: 'smooth' });
          }, 100);
      } else {
          alert("AI không trả về câu hỏi nào. Vui lòng thử lại với cấu hình khác.");
      }
    } catch (error) {
      alert((error as Error).message);
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePublish = () => {
    if (generatedQuestions.length === 0) return;

    const newQuiz: Quiz = {
      id: `quiz_${Date.now()}`,
      title: `${subject} - ${grade} - ${lesson}`,
      config: {
        subject, grade, lesson,
        totalQuestions: {
            [QuestionType.MULTIPLE_CHOICE]: mcCount,
            [QuestionType.TRUE_FALSE]: tfCount,
            [QuestionType.SHORT_ANSWER]: saCount,
        },
        difficultyDistribution: {
            [Difficulty.RECALL]: recallCount,
            [Difficulty.UNDERSTAND]: understandCount,
            [Difficulty.APPLY]: applyCount,
        }
      },
      questions: generatedQuestions,
      createdAt: Date.now(),
      isActive: publishImmediately,
    };

    saveQuiz(newQuiz);
    setQuizSaved(true);
    alert(publishImmediately 
      ? "Đề thi đã được phát hành! Học sinh có thể làm bài ngay." 
      : "Đề thi đã được lưu nháp. Vào tab 'Quản lý' để phát hành khi cần.");
  };

  const handleDeleteQuiz = (id: string) => {
    if (confirm("Bạn có chắc chắn muốn xóa đề thi này không? Dữ liệu không thể khôi phục.")) {
        deleteQuiz(id);
        loadData(); // Reload list
        if (viewingQuiz?.id === id) setViewingQuiz(null);
    }
  };

  const handleToggleStatus = (id: string, currentStatus: boolean) => {
    updateQuizStatus(id, !currentStatus);
    loadData(); // Reload list
    // If viewing this quiz, update local view state too
    if (viewingQuiz && viewingQuiz.id === id) {
        setViewingQuiz({...viewingQuiz, isActive: !currentStatus});
    }
  };

  const clean = (str: string) => str.replace(/<[^>]*>?/gm, '');

  const handleExportWord = (title: string, questionsData: Question[]) => {
    // 1. Header Section
    const headerContent = `
      <div style="font-family: 'Times New Roman', serif;">
        <table style="width: 100%; border: none; margin-bottom: 20px;">
          <tr>
            <td style="text-align: center; vertical-align: top; width: 40%;">
              <p style="margin: 0; font-size: 11pt; font-weight: bold;">TRƯỜNG THPT LỘC BÌNH</p>
              <p style="margin: 0; font-weight: bold; text-decoration: underline;">ĐỀ CHÍNH THỨC</p>
            </td>
            <td style="text-align: center; vertical-align: top;">
              <p style="margin: 0; font-weight: bold; font-size: 13pt; text-transform: uppercase;">ĐỀ KIỂM TRA MÔN: ${subject.toUpperCase()}</p>
              <p style="margin: 0; font-size: 12pt;">Bài: ${lesson} - Lớp: ${grade}</p>
              <p style="margin: 0; font-size: 12pt; font-style: italic;">Thời gian làm bài: 45 phút</p>
            </td>
          </tr>
        </table>
      </div>
    `;

    // 2. Exam Content
    let examContent = `<div style="font-family: 'Times New Roman', serif; font-size: 13pt;">`;

    // Sort: MC -> TF -> SA
    const sortedQuestions = [...questionsData].sort((a, b) => {
        const typeOrder = { [QuestionType.MULTIPLE_CHOICE]: 1, [QuestionType.TRUE_FALSE]: 2, [QuestionType.SHORT_ANSWER]: 3 };
        return typeOrder[a.type] - typeOrder[b.type];
    });

    const hasMC = sortedQuestions.some(q => q.type === QuestionType.MULTIPLE_CHOICE);
    const hasTF = sortedQuestions.some(q => q.type === QuestionType.TRUE_FALSE);
    const hasSA = sortedQuestions.some(q => q.type === QuestionType.SHORT_ANSWER);

    // -- Part I: Multiple Choice
    if (hasMC) {
        examContent += `<p style="font-weight: bold; font-size: 14pt; margin-top: 10px;">PHẦN I. TRẮC NGHIỆM KHÁCH QUAN</p>`;
        const mcqs = sortedQuestions.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
        mcqs.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 10px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            if (q.options) {
                examContent += `<table style="width: 100%; margin-top: 5px; margin-left: 20px;"><tr>`;
                q.options.forEach((opt, i) => {
                    const letter = String.fromCharCode(65 + i);
                    if (i > 0 && i % 2 === 0) examContent += `</tr><tr>`;
                    examContent += `<td style="padding: 2px 10px;"><strong>${letter}.</strong> ${clean(opt)}</td>`;
                });
                examContent += `</tr></table>`;
            }
            examContent += `</div>`;
        });
    }

    // -- Part II: True/False
    if (hasTF) {
        examContent += `<p style="font-weight: bold; font-size: 14pt; margin-top: 15px;">PHẦN II. TRẮC NGHIỆM ĐÚNG SAI</p>`;
        const tfs = sortedQuestions.filter(q => q.type === QuestionType.TRUE_FALSE);
        tfs.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 15px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            if (q.options) {
                examContent += `<table border="1" style="border-collapse: collapse; width: 100%; margin-top: 5px; font-size: 12pt;">`;
                examContent += `<tr style="background-color: #f0f0f0;"><th style="padding: 5px;">Ý</th><th style="padding: 5px; text-align: left;">Nội dung</th><th style="padding: 5px; width: 50px;">Đúng</th><th style="padding: 5px; width: 50px;">Sai</th></tr>`;
                q.options.forEach((opt, i) => {
                    const letter = String.fromCharCode(97 + i); // a, b, c, d
                    examContent += `<tr>
                        <td style="text-align: center; font-weight: bold; width: 40px;">${letter})</td>
                        <td style="padding: 5px;">${clean(opt)}</td>
                        <td style="text-align: center;"></td>
                        <td style="text-align: center;"></td>
                    </tr>`;
                });
                examContent += `</table>`;
            }
            examContent += `</div>`;
        });
    }

    // -- Part III: Short Answer
    if (hasSA) {
        examContent += `<p style="font-weight: bold; font-size: 14pt; margin-top: 15px;">PHẦN III. TRẮC NGHIỆM TRẢ LỜI NGẮN / TỰ LUẬN</p>`;
        const sas = sortedQuestions.filter(q => q.type === QuestionType.SHORT_ANSWER);
        sas.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 10px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            examContent += `<p style="margin-left: 0px; margin-top: 10px; border: 1px solid #ccc; height: 100px; padding: 10px;">(Thí sinh làm bài vào đây)...</p>`;
            examContent += `</div>`;
        });
    }

    examContent += `</div>`;

    const fullContent = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
      <head>
        <meta charset='utf-8'>
        <title>${title}</title>
      </head>
      <body>
        ${headerContent}
        ${examContent}
      </body>
      </html>
    `;

    downloadDoc(fullContent, `De_Thi_${subject}_${grade}_${Date.now()}.doc`);
  };

  const handleExportAnswerKey = (title: string, questionsData: Question[]) => {
    // Calculate Stats
    const mcqs = questionsData.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
    const tfs = questionsData.filter(q => q.type === QuestionType.TRUE_FALSE);
    const sas = questionsData.filter(q => q.type === QuestionType.SHORT_ANSWER);

    // Heuristic Score Calculation (Assuming standard Total = 10)
    // Rule: MC ~0.25/q. TF ~1.0/q. SA = Remainder.
    const mcPointPerQ = 0.25;
    const tfPointPerQ = 1.0; 

    let mcTotal = mcqs.length * mcPointPerQ;
    let tfTotal = tfs.length * tfPointPerQ;

    // Adjust if total > 10
    if (mcTotal + tfTotal > 10) {
        // Fallback: Proportional
    }

    let saTotal = 10 - mcTotal - tfTotal;
    if (saTotal < 0) saTotal = 0;

    const saPointPerQ = sas.length > 0 ? Number((saTotal / sas.length).toFixed(2)) : 0;

    let keyContent = `
      <div style="font-family: 'Times New Roman', serif; font-size: 13pt;">
      <h3 style="text-align: center; text-transform: uppercase;">HƯỚNG DẪN CHẤM & ĐÁP ÁN</h3>
      <p style="text-align: center; font-weight: bold; margin-bottom: 20px;">Môn: ${subject} - ${grade}</p>

      <div style="margin-bottom: 20px; border: 1px solid #000; padding: 10px;">
        <p style="font-weight: bold; text-decoration: underline;">LƯU Ý CHẤM ĐIỂM:</p>
        <ul style="list-style-type: square; margin-top: 5px;">
            <li><strong>Phần trắc nghiệm:</strong> ${mcTotal} điểm. Mỗi câu trả lời đúng được ${mcPointPerQ} điểm.</li>
            <li><strong>Phần trắc nghiệm đúng/sai:</strong> ${tfTotal} điểm. Mỗi câu có 4 ý.
                <br/>- Đúng 1 ý: 0.1 điểm.
                <br/>- Đúng 2 ý: 0.25 điểm.
                <br/>- Đúng 3 ý: 0.5 điểm.
                <br/>- Đúng 4 ý: 1.0 điểm. 
                <i>(Hoặc theo quy tắc: ${tfPointPerQ} điểm/câu, chia đều 0.25 điểm/ý theo yêu cầu).</i>
            </li>
            <li><strong>Phần tự luận:</strong> ${Number(saTotal.toFixed(2))} điểm. Căn cứ vào các bước làm bài để cho điểm thành phần.</li>
        </ul>
      </div>
    `;

    // 1. MC Table
    if (mcqs.length > 0) {
        keyContent += `<p style="font-weight: bold; margin-top: 10px;">PHẦN I. TRẮC NGHIỆM (${mcTotal} điểm)</p>`;
        keyContent += `<table border="1" style="border-collapse: collapse; width: 100%; text-align: center; font-size: 11pt; margin-bottom: 20px;">`;

        const cols = 10;
        let currentRow = "<tr>";
        let count = 0;

        mcqs.forEach((q, idx) => {
             let letter = "?";
             if (q.options) {
                 const matchIdx = q.options.findIndex(o => o.trim() === q.correctAnswer.trim());
                 if (matchIdx !== -1) letter = String.fromCharCode(65 + matchIdx);
                 else {
                     // Fuzzy match
                     const fuzzyIdx = q.options.findIndex(o => q.correctAnswer.includes(o) || o.includes(q.correctAnswer));
                     if (fuzzyIdx !== -1) letter = String.fromCharCode(65 + fuzzyIdx);
                 }
             }

             // Question index is based on overall sort, but here we just list them sequentially in Part I
             currentRow += `<td style="padding: 5px;"><b>${idx + 1}</b>.${letter}</td>`;
             count++;
             if (count === cols) {
                 currentRow += "</tr>";
                 keyContent += currentRow;
                 currentRow = "<tr>";
                 count = 0;
             }
        });

        if (count > 0) {
            while (count < cols) {
                currentRow += "<td></td>";
                count++;
            }
            currentRow += "</tr>";
            keyContent += currentRow;
        }
        keyContent += `</table>`;
    }

    // 2. TF Table
    if (tfs.length > 0) {
        keyContent += `<p style="font-weight: bold; margin-top: 10px;">PHẦN II. TRẮC NGHIỆM ĐÚNG/SAI (${tfTotal} điểm)</p>`;

        tfs.forEach((q, idx) => {
            keyContent += `<div style="margin-bottom: 10px;">`;
            keyContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;

            // Parse answers string "Đúng, Sai, Đúng, Sai" or "True, False..."
            const answers = q.correctAnswer.split(/[,|]/).map(s => s.trim());

            keyContent += `<table border="1" style="border-collapse: collapse; width: 60%; margin-top: 5px; font-size: 11pt;">`;
            keyContent += `<tr style="background-color: #eee;"><th style="width: 50px;">Ý</th><th>Lệnh hỏi</th><th style="width: 100px;">Đáp án</th></tr>`;

            if (q.options) {
                q.options.forEach((opt, i) => {
                    const letter = String.fromCharCode(97 + i); // a,b,c,d
                    const ans = answers[i] || "N/A";
                    keyContent += `<tr>
                        <td style="text-align: center;">${letter})</td>
                        <td style="padding: 5px;">${clean(opt)}</td>
                        <td style="text-align: center; font-weight: bold;">${ans}</td>
                    </tr>`;
                });
            }
            keyContent += `</table>`;
            if (q.explanation) {
                keyContent += `<p style="margin: 5px 0 0 0; font-style: italic;">* Hướng dẫn: ${clean(q.explanation)}</p>`;
            }
            keyContent += `</div>`;
        });
    }

    // 3. Short Answer
    if (sas.length > 0) {
        keyContent += `<p style="font-weight: bold; margin-top: 10px;">PHẦN III. TỰ LUẬN / TRẢ LỜI NGẮN (${Number(saTotal.toFixed(2))} điểm)</p>`;
        keyContent += `<table border="1" style="border-collapse: collapse; width: 100%; font-size: 12pt;">`;
        keyContent += `<tr style="background-color: #eee; text-align: center;">
            <th style="padding: 5px; width: 10%;">Câu</th>
            <th style="padding: 5px;">Nội dung / Hướng dẫn chấm</th>
            <th style="padding: 5px; width: 15%;">Điểm</th>
        </tr>`;

        sas.forEach((q, idx) => {
            keyContent += `<tr>
                <td style="text-align: center; font-weight: bold; vertical-align: top; padding: 5px;">${idx + 1}</td>
                <td style="padding: 5px; vertical-align: top;">
                    <p style="margin: 0 0 5px 0;"><strong>Đáp án:</strong> ${clean(q.correctAnswer)}</p>
                    <p style="margin: 0;"><em>${clean(q.explanation || '')}</em></p>
                </td>
                <td style="text-align: center; vertical-align: middle;">${saPointPerQ}</td>
            </tr>`;
        });
        keyContent += `</table>`;
    }

    keyContent += `</div>`;

    const fullContent = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
      <head>
        <meta charset='utf-8'>
        <title>${title} - Đáp án</title>
      </head>
      <body>${keyContent}</body>
      </html>
    `;

    downloadDoc(fullContent, `Dap_An_${subject}_${grade}_${Date.now()}.doc`);
  };

  const downloadDoc = (content: string, filename: string) => {
    const blob = new Blob(['\ufeff', content], {
      type: 'application/msword'
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadExcel = () => {
    const dataToExport = viewingQuiz 
      ? attempts.filter(a => a.quizId === viewingQuiz.id)
      : attempts;

    if (dataToExport.length === 0) {
      alert("Chưa có dữ liệu bài làm nào.");
      return;
    }

    const headers = ["Mã đề", "Tên đề thi", "Tên học sinh", "Lớp", "Điểm số", "Thời gian nộp"];
    const rows = dataToExport.map(a => {
        const quizTitle = quizzes.find(q => q.id === a.quizId)?.title || a.quizId;
        return [
            `"${a.quizId}"`,
            `"${quizTitle}"`, 
            `"${a.studentName}"`, 
            `"${a.studentClass}"`, 
            `${a.score}/${a.totalScore}`, 
            `"${new Date(a.timestamp).toLocaleString()}"`
        ].join(",");
    });

    const csvContent = "data:text/csv;charset=utf-8," + "\uFEFF" + [headers.join(","), ...rows].join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", viewingQuiz ? `ket_qua_${viewingQuiz.title}.csv` : "tat_ca_ket_qua.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Helper to render question list
  const renderQuestionList = (questions: Question[]) => (
    <div className="space-y-6">
      {questions.map((q, idx) => (
        <div key={q.id} className="p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex justify-between items-start mb-2">
            <span className="font-bold text-blue-800">Câu {idx + 1} ({q.type === QuestionType.MULTIPLE_CHOICE ? 'TN' : q.type === QuestionType.TRUE_FALSE ? 'Đ/S' : 'TLN'})</span>
            <span className={`text-xs px-2 py-1 rounded ${q.difficulty === Difficulty.RECALL ? 'bg-green-100 text-green-800' : q.difficulty === Difficulty.UNDERSTAND ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800'}`}>
              {q.difficulty === Difficulty.RECALL ? 'Nhận biết' : q.difficulty === Difficulty.UNDERSTAND ? 'Thông hiểu' : 'Vận dụng'}
            </span>
          </div>
          <p className="mb-3 text-gray-800 font-medium">{q.text}</p>

          {q.type === QuestionType.MULTIPLE_CHOICE && q.options && (
            <div className="grid grid-cols-1 gap-2 ml-4">
              {q.options.map((opt, i) => {
                const isCorrect = opt === q.correctAnswer;
                return (
                  <div key={i} className={`p-2 rounded border ${isCorrect ? 'bg-green-50 border-green-300' : 'bg-white border-gray-200'}`}>
                    <span className={`font-semibold mr-2 ${isCorrect ? 'underline decoration-2 decoration-green-600 text-green-700 font-bold' : ''}`}>
                      {String.fromCharCode(65 + i)}.
                    </span> 
                    {opt}
                  </div>
                );
              })}
              {q.explanation && (
                <div className="mt-2 p-3 bg-blue-50 border border-blue-100 rounded text-sm text-blue-900">
                  <span className="font-bold text-blue-700">Lời giải: </span>{q.explanation}
                </div>
              )}
            </div>
          )}

          {q.type === QuestionType.TRUE_FALSE && q.options && (
              <div className="ml-4 space-y-3">
                <div className="bg-gray-50 p-3 rounded border border-gray-200">
                    <p className="text-sm font-bold text-gray-600 mb-2">Các mệnh đề:</p>
                    {q.options.map((opt, i) => {
                        // Extract corresponding answer key for this index
                        const answers = q.correctAnswer.split(/[,|]/).map(s => s.trim());
                        const ans = answers[i] || "?";
                        const isTrue = ans.toLowerCase().includes('đúng') || ans.toLowerCase() === 'true';

                        return (
                            <div key={i} className="flex justify-between items-center py-2 border-b last:border-0">
                                <span className="flex-1"><span className="font-bold mr-2">{String.fromCharCode(97+i)})</span> {opt}</span>
                                <span className={`ml-4 px-2 py-0.5 rounded text-xs font-bold ${isTrue ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                    {ans}
                                </span>
                            </div>
                        )
                    })}
                </div>
                {q.explanation && (
                    <div className="mt-2 p-3 bg-blue-50 border border-blue-100 rounded text-sm text-blue-900">
                        <span className="font-bold text-blue-700">Giải thích chi tiết: </span>{q.explanation}
                    </div>
                )}
              </div>
          )}

          {q.type === QuestionType.SHORT_ANSWER && (
            <div className="ml-4 space-y-2">
                <div className="p-2 bg-yellow-50 border border-yellow-200 rounded text-yellow-800">
                <strong>Đáp án mẫu:</strong> {q.correctAnswer}
                </div>
                {q.explanation && (
                    <div className="p-3 bg-blue-50 border border-blue-100 rounded text-sm text-blue-900">
                        <span className="font-bold text-blue-700">Gợi ý/Giải thích: </span>{q.explanation}
                    </div>
                )}
            </div>
          )}
        </div>
      ))}
    </div>
  );

  const inputClass = "w-full rounded-md shadow-sm p-1.5 text-sm border border-blue-400 bg-blue-50 text-blue-900 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 font-medium placeholder-blue-400";
  const numberInputClass = "w-full mt-0.5 p-1.5 rounded-md text-sm border border-blue-400 bg-blue-50 text-blue-900 focus:ring-blue-500 font-bold text-center disabled:opacity-50";

  return (
