                    >
                      {GRADES.map(g => <option key={g} value={g}>{g}</option>)}
                    </select>
                  </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-700 mb-0.5">Tên bài học</label>
                <input 
                  type="text" 
