               <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                 {/* Left: Questions List */}
                 <div>
                   <h3 className="text-lg font-semibold mb-4 text-blue-800 border-b pb-2">Nội dung Đề thi</h3>
                   <div className="max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
                     {renderQuestionList(viewingQuiz.questions)}
                   </div>
                 </div>

                 {/* Right: Student Results */}
                 <div>
                    <h3 className="text-lg font-semibold mb-4 text-blue-800 border-b pb-2">Danh sách Bài làm ({attempts.filter(a => a.quizId === viewingQuiz.id).length})</h3>
                    <div className="overflow-x-auto">
                      <table className="w-full text-left border-collapse">
                        <thead>
                          <tr className="bg-gray-100 text-gray-600 uppercase text-xs">
                            <th className="p-3 border-b">Học sinh</th>
                            <th className="p-3 border-b">Lớp</th>
                            <th className="p-3 border-b text-center">Điểm</th>
                            <th className="p-3 border-b text-right">Thời gian</th>
                          </tr>
                        </thead>
                        <tbody>
                          {attempts.filter(a => a.quizId === viewingQuiz.id).length === 0 ? (
                            <tr><td colSpan={4} className="p-4 text-center text-gray-400">Chưa có học sinh làm bài</td></tr>
                          ) : (
                            attempts
                              .filter(a => a.quizId === viewingQuiz.id)
                              .map(attempt => (
                                <tr key={attempt.id} className="hover:bg-gray-50 border-b last:border-0">
                                  <td className="p-3 font-medium">{attempt.studentName}</td>
                                  <td className="p-3">{attempt.studentClass}</td>
                                  <td className="p-3 text-center font-bold">
                                    <span className={attempt.score / attempt.totalScore >= 0.5 ? 'text-green-600' : 'text-red-500'}>
                                      {attempt.score}/{attempt.totalScore}
                                    </span>
                                  </td>
                                  <td className="p-3 text-sm text-right text-gray-500">{new Date(attempt.timestamp).toLocaleString()}</td>
                                </tr>
                              ))
                          )}
                        </tbody>
                      </table>
                    </div>
                 </div>
               </div>
             </div>
           ) : (
             // List View: All Quizzes
             <div>
               <h2 className="text-xl font-bold text-gray-800 mb-6">Quản lý Danh sách Đề thi</h2>
               <div className="overflow-x-auto">
                 <table className="w-full text-left border-collapse">
                   <thead>
                     <tr className="bg-blue-50 text-blue-800 uppercase text-xs">
                       <th className="p-3 border-b border-blue-200">Ngày tạo</th>
                       <th className="p-3 border-b border-blue-200">Tên đề thi</th>
                       <th className="p-3 border-b border-blue-200 text-center">Số câu</th>
                       <th className="p-3 border-b border-blue-200 text-center">Lượt làm</th>
                       <th className="p-3 border-b border-blue-200 text-center">Trạng thái (HS)</th>
                       <th className="p-3 border-b border-blue-200 text-right">Thao tác</th>
                     </tr>
                   </thead>
                   <tbody>
                     {quizzes.length === 0 ? (
                       <tr>
                         <td colSpan={6} className="p-8 text-center text-gray-400">Chưa có đề thi nào. Hãy sang tab "Soạn đề thi" để tạo mới.</td>
                       </tr>
                     ) : (
                       quizzes.slice().reverse().map((quiz) => {
                         const attemptCount = attempts.filter(a => a.quizId === quiz.id).length;
                         return (
                           <tr key={quiz.id} className="hover:bg-gray-50 border-b border-gray-100 last:border-0">
                             <td className="p-3 text-sm text-gray-600 whitespace-nowrap">{new Date(quiz.createdAt).toLocaleDateString()}</td>
                             <td className="p-3 font-medium text-gray-900">
                                {quiz.title}
                                <div className="text-xs text-gray-500 font-normal">{quiz.config.subject} - {quiz.config.grade}</div>
                             </td>
                             <td className="p-3 text-center">{quiz.questions.length}</td>
                             <td className="p-3 text-center">
                               <span className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full font-bold">{attemptCount}</span>
                             </td>
                             <td className="p-3 text-center">
                                <div className="flex flex-col items-center cursor-pointer" onClick={(e) => { e.stopPropagation(); handleToggleStatus(quiz.id, quiz.isActive); }}>
                                    <div className={`relative inline-flex items-center h-6 rounded-full w-11 transition-colors focus:outline-none ${quiz.isActive ? 'bg-green-500' : 'bg-gray-300'}`}>
                                        <span className={`transform transition ease-in-out duration-200 inline-block w-4 h-4 transform bg-white rounded-full shadow ${quiz.isActive ? 'translate-x-6' : 'translate-x-1'}`} />
                                    </div>
                                    <span className={`text-[10px] mt-1 font-bold ${quiz.isActive ? 'text-green-600' : 'text-gray-400'}`}>
                                        {quiz.isActive ? 'Đang mở' : 'Đã đóng'}
                                    </span>
                                </div>
                             </td>
                             <td className="p-3 text-right">
                               <div className="flex items-center justify-end gap-2">
                                    <button 
                                        onClick={() => setViewingQuiz(quiz)}
                                        className="text-blue-600 hover:bg-blue-100 p-2 rounded transition"
                                        title="Xem chi tiết"
                                    >
                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg>
                                    </button>
                                    <button 
                                        onClick={() => handleDeleteQuiz(quiz.id)}
                                        className="text-red-500 hover:bg-red-100 p-2 rounded transition"
                                        title="Xóa đề thi"
                                    >
                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                                    </button>
                               </div>
                             </td>
                           </tr>
                         );
                       })
                     )}
                   </tbody>
                 </table>
               </div>
             </div>
           )}
        </div>
      )}
    </div>
  );
};

export default TeacherDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { SUBJECTS, GRADES, QuizConfig, QuestionType, Difficulty, Question, Quiz, StudentAttempt } from '../types';
import { generateQuizQuestions, MatrixInput, analyzeMatrixFromInput } from '../services/geminiService';
import { saveQuiz, getQuizzes, getAttempts, deleteQuiz, updateQuizStatus } from '../services/storageService';

// Declare types for global libraries
declare const mammoth: any;
declare const pdfjsLib: any;

const TeacherDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'create' | 'results'>('create');

  // Form State
  const [subject, setSubject] = useState(SUBJECTS[0]);
  const [grade, setGrade] = useState(GRADES[0]);
  const [lesson, setLesson] = useState('');

  const [mcCount, setMcCount] = useState(5);
  const [tfCount, setTfCount] = useState(0);
  const [saCount, setSaCount] = useState(0);

  const [recallCount, setRecallCount] = useState(3);
  const [understandCount, setUnderstandCount] = useState(2);
  const [applyCount, setApplyCount] = useState(0);

  // File state
  const [matrixFile, setMatrixFile] = useState<{
    name: string;
    type: 'image' | 'text';
    data: string;
    mimeType?: string;
  } | null>(null);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedQuestions, setGeneratedQuestions] = useState<Question[]>([]);
  const [quizSaved, setQuizSaved] = useState(false);
  const [publishImmediately, setPublishImmediately] = useState(true);

  // Results & Viewing State
  const [attempts, setAttempts] = useState<StudentAttempt[]>([]);
  const [quizzes, setQuizzes] = useState<Quiz[]>([]);
  const [viewingQuiz, setViewingQuiz] = useState<Quiz | null>(null);

  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadData = () => {
    setAttempts(getAttempts());
    setQuizzes(getQuizzes());
  };

  useEffect(() => {
    if (activeTab === 'results') {
      loadData();
      setViewingQuiz(null);
    }
  }, [activeTab]);

  const processMatrixData = async (data: MatrixInput, fileName: string) => {
    if (data.type === 'image') {
      setMatrixFile({ name: fileName, type: 'image', data: data.data, mimeType: data.mimeType });
    } else {
      setMatrixFile({ name: fileName, type: 'text', data: data.content });
    }

    setIsAnalyzing(true);
    try {
      const result = await analyzeMatrixFromInput(data);
      setMcCount(result.counts[QuestionType.MULTIPLE_CHOICE]);
      setTfCount(result.counts[QuestionType.TRUE_FALSE]);
      setSaCount(result.counts[QuestionType.SHORT_ANSWER]);
      setRecallCount(result.difficulty[Difficulty.RECALL]);
      setUnderstandCount(result.difficulty[Difficulty.UNDERSTAND]);
      setApplyCount(result.difficulty[Difficulty.APPLY]);
    } catch (e) {
      console.error("Auto-fill failed", e);
    } finally {
      setIsAnalyzing(false);
      setIsProcessingFile(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessingFile(true);
    try {
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64String = reader.result as string;
          const matches = base64String.match(/^data:(.+);base64,(.+)$/);
          if (matches) {
            processMatrixData({ type: 'image', mimeType: matches[1], data: matches[2] }, file.name);
          } else {
            setIsProcessingFile(false);
          }
        };
        reader.readAsDataURL(file);
      } else if (file.name.endsWith('.docx')) {
        const reader = new FileReader();
        reader.onloadend = (event) => {
          const arrayBuffer = event.target?.result as ArrayBuffer;
          mammoth.extractRawText({ arrayBuffer: arrayBuffer })
            .then((result: any) => {
              processMatrixData({ type: 'text', content: result.value }, file.name);
            })
            .catch((err: any) => {
              console.error(err);
              alert("Lỗi đọc file Word.");
              setIsProcessingFile(false);
            });
        };
        reader.readAsArrayBuffer(file);
      } else if (file.type === 'application/pdf' || file.name.endsWith('.pdf')) {
        const reader = new FileReader();
        reader.onloadend = async (event) => {
          const arrayBuffer = event.target?.result as ArrayBuffer;
          try {
            const loadingTask = pdfjsLib.getDocument(arrayBuffer);
            const pdf = await loadingTask.promise;
            let fullText = "";
            for (let i = 1; i <= pdf.numPages; i++) {
                const page = await pdf.getPage(i);
                const textContent = await page.getTextContent();
                const pageText = textContent.items.map((item: any) => item.str).join(' ');
                fullText += `--- Trang ${i} ---\n${pageText}\n`;
            }
            processMatrixData({ type: 'text', content: fullText }, file.name);
          } catch (err) {
            console.error(err);
            alert("Lỗi đọc file PDF.");
            setIsProcessingFile(false);
          }
        };
        reader.readAsArrayBuffer(file);
      } else {
        alert("Định dạng file không hỗ trợ.");
        setIsProcessingFile(false);
      }
    } catch (e) {
      console.error(e);
      alert("Có lỗi xảy ra khi xử lý file.");
      setIsProcessingFile(false);
    }
  };

  const clearFile = () => {
    setMatrixFile(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleGenerate = async () => {
    if (!lesson) {
      alert("Vui lòng nhập tên bài học");
      return;
    }
    const totalQ = mcCount + tfCount + saCount;
    if (totalQ === 0) {
      alert("Vui lòng nhập số lượng câu hỏi.");
      return;
    }
    setIsGenerating(true);
    setQuizSaved(false);
    setGeneratedQuestions([]);
    const config: QuizConfig = {
      subject, grade, lesson,
      totalQuestions: {
        [QuestionType.MULTIPLE_CHOICE]: mcCount,
        [QuestionType.TRUE_FALSE]: tfCount,
        [QuestionType.SHORT_ANSWER]: saCount,
      },
      difficultyDistribution: {
        [Difficulty.RECALL]: recallCount,
        [Difficulty.UNDERSTAND]: understandCount,
        [Difficulty.APPLY]: applyCount,
      }
    };
    try {
      let matrixInput: MatrixInput | undefined = undefined;
      if (matrixFile) {
        if (matrixFile.type === 'image' && matrixFile.mimeType) {
          matrixInput = { type: 'image', data: matrixFile.data, mimeType: matrixFile.mimeType };
        } else if (matrixFile.type === 'text') {
          matrixInput = { type: 'text', content: matrixFile.data };
        }
      }
      const questions = await generateQuizQuestions(config, matrixInput);
      if (questions && questions.length > 0) {
          setGeneratedQuestions(questions);
          setTimeout(() => {
            previewRef.current?.scrollIntoView({ behavior: 'smooth' });
          }, 100);
      } else {
          alert("AI không trả về câu hỏi nào.");
      }
    } catch (error) {
      alert((error as Error).message);
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePublish = () => {
    if (generatedQuestions.length === 0) return;
    const newQuiz: Quiz = {
      id: `quiz_${Date.now()}`,
      title: `${subject} - ${grade} - ${lesson}`,
      config: {
        subject, grade, lesson,
        totalQuestions: {
            [QuestionType.MULTIPLE_CHOICE]: mcCount,
            [QuestionType.TRUE_FALSE]: tfCount,
            [QuestionType.SHORT_ANSWER]: saCount,
        },
        difficultyDistribution: {
            [Difficulty.RECALL]: recallCount,
            [Difficulty.UNDERSTAND]: understandCount,
            [Difficulty.APPLY]: applyCount,
        }
      },
      questions: generatedQuestions,
      createdAt: Date.now(),
      isActive: publishImmediately,
    };
    saveQuiz(newQuiz);
    setQuizSaved(true);
    alert("Đề thi đã được lưu thành công.");
  };

  const handleDeleteQuiz = (id: string) => {
    if (confirm("Xóa đề thi này?")) {
        deleteQuiz(id);
        loadData();
        if (viewingQuiz?.id === id) setViewingQuiz(null);
    }
  };

  const handleToggleStatus = (id: string, currentStatus: boolean) => {
    updateQuizStatus(id, !currentStatus);
    loadData();
    if (viewingQuiz && viewingQuiz.id === id) {
        setViewingQuiz({...viewingQuiz, isActive: !currentStatus});
    }
  };

  // Helper to remove redundant A. B. C. D. from AI generated content
  const cleanOption = (str: string) => {
    return str.replace(/^[A-D]\.\s*/i, '').replace(/<[^>]*>?/gm, '');
  };

  const clean = (str: string) => str.replace(/<[^>]*>?/gm, '');

  const shuffleArray = <T,>(array: T[]): T[] => {
    const newArr = [...array];
    for (let i = newArr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
    }
    return newArr;
  };

  const handleExportWord = (title: string, questionsData: Question[], quizCode: string = "101") => {
    const headerContent = `
      <div style="font-family: 'Times New Roman', serif;">
        <table style="width: 100%; border: none; margin-bottom: 20px;">
          <tr>
            <td style="text-align: center; vertical-align: top; width: 45%;">
              <p style="margin: 0; font-size: 11pt; font-weight: bold;">TRƯỜNG THPT LỘC BÌNH</p>
              <p style="margin: 0; font-weight: bold; border: 1px solid #000; display: inline-block; padding: 2px 10px; margin-top: 5px;">ĐỀ CHÍNH THỨC</p>
              <div style="margin-top: 10px; border: 1px solid #000; width: 100px; margin-left: auto; margin-right: auto; padding: 5px;">
                <p style="margin: 0; font-size: 10pt; font-weight: bold;">Mã đề: ${quizCode}</p>
              </div>
            </td>
            <td style="text-align: center; vertical-align: top;">
              <p style="margin: 0; font-weight: bold; font-size: 11pt; text-transform: uppercase;">KIỂM TRA CUỐI HỌC KÌ I LỚP 10 NĂM HỌC 2025 - 2026</p>
              <p style="margin: 0; font-weight: bold; font-size: 12pt;">MÔN: ${subject.toUpperCase()}</p>
              <p style="margin: 0; font-size: 11pt; font-style: italic;">Thời gian làm bài: 45 phút</p>
              <p style="margin: 0; font-size: 10pt;">Đề kiểm tra gồm có 02 trang, (${questionsData.length} câu hỏi)</p>
            </td>
          </tr>
        </table>
        <p style="margin-bottom: 20px; font-size: 11pt;">Họ, tên học sinh: ............................................................................ Lớp: .............................</p>
      </div>
    `;

    let examContent = `<div style="font-family: 'Times New Roman', serif; font-size: 12pt;">`;

    const sortedQuestions = questionsData;
    const mcqs = sortedQuestions.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
    const tfs = sortedQuestions.filter(q => q.type === QuestionType.TRUE_FALSE);
    const sas = sortedQuestions.filter(q => q.type === QuestionType.SHORT_ANSWER);

    if (mcqs.length > 0) {
        examContent += `<p style="font-weight: bold; margin-top: 10px;">PHẦN I (4,0 điểm). Thí sinh trả lời từ câu 1 đến câu ${mcqs.length}. Mỗi câu hỏi thí sinh chỉ chọn 1 phương án.</p>`;
        mcqs.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 10px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            if (q.options) {
                examContent += `<table style="width: 100%; margin-top: 5px; margin-left: 10px;"><tr>`;
                q.options.forEach((opt, i) => {
                    const letter = String.fromCharCode(65 + i);
                    if (i > 0 && i % 2 === 0) examContent += `</tr><tr>`;
                    examContent += `<td style="padding: 2px 5px; width: 50%;"><strong>${letter}.</strong> ${cleanOption(opt)}</td>`;
                });
                examContent += `</tr></table>`;
            }
            examContent += `</div>`;
        });
    }

    if (tfs.length > 0) {
        examContent += `<p style="font-weight: bold; margin-top: 15px;">PHẦN II (2,0 điểm). Thí sinh trả lời từ câu 1 đến câu ${tfs.length}. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.</p>`;
        tfs.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 15px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            if (q.options) {
                q.options.forEach((opt, i) => {
                    const letter = String.fromCharCode(97 + i);
                    examContent += `<p style="margin: 2px 0 2px 20px;"><strong>${letter})</strong> ${clean(opt)}</p>`;
                });
            }
            examContent += `</div>`;
        });
    }

    if (sas.length > 0) {
        examContent += `<p style="font-weight: bold; margin-top: 15px;">PHẦN III (1,0 điểm). Thí sinh trả lời các câu hỏi sau.</p>`;
        sas.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 10px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            examContent += `<p style="margin-top: 5px; border-bottom: 1px dotted #000; height: 40px;"></p>`;
            examContent += `</div>`;
        });
    }

    examContent += `</div><p style="text-align: center; font-weight: bold; margin-top: 30px;">..............Hết.............</p>`;

    const fullContent = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
      <head><meta charset='utf-8'></head>
      <body>${headerContent}${examContent}</body>
      </html>
    `;
    downloadDoc(fullContent, `De_Thi_${quizCode}_${Date.now()}.doc`);
  };

  const handleExport4Versions = (quiz: Quiz) => {
    const originalQuestions = quiz.questions;

    for (let v = 0; v < 4; v++) {
      const quizCode = (101 + v).toString();

      const mcqs = originalQuestions.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
      const tfs = originalQuestions.filter(q => q.type === QuestionType.TRUE_FALSE);
      const sas = originalQuestions.filter(q => q.type === QuestionType.SHORT_ANSWER);

      // Mix MCQs
      const mixedMcqs = shuffleArray(mcqs).map(q => {
        if (!q.options) return q;
        const shuffledOptions = shuffleArray([...q.options]);
        return { ...q, options: shuffledOptions };
      });

      // Mix TFs
      const mixedTfs = shuffleArray(tfs);

      // Mix SAS
      const mixedSas = shuffleArray(sas);

      const mixedQuestions = [...mixedMcqs, ...mixedTfs, ...mixedSas];
      handleExportWord(quiz.title, mixedQuestions, quizCode);
    }
    alert("Hệ thống đã tạo 4 mã đề (101, 102, 103, 104) thành công.");
  };

  const handleExportAnswerKey = (title: string, questionsData: Question[]) => {
    const mcqs = questionsData.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
    const tfs = questionsData.filter(q => q.type === QuestionType.TRUE_FALSE);
    const sas = questionsData.filter(q => q.type === QuestionType.SHORT_ANSWER);

    let keyContent = `
      <div style="font-family: 'Times New Roman', serif; font-size: 12pt;">
      <h3 style="text-align: center; text-transform: uppercase;">HƯỚNG DẪN CHẤM & ĐÁP ÁN</h3>
      <p style="text-align: center; font-weight: bold; margin-bottom: 20px;">Môn: ${subject} - ${grade}</p>
    `;

    if (mcqs.length > 0) {
        keyContent += `<p style="font-weight: bold;">PHẦN I. TRẮC NGHIỆM</p><table border="1" style="border-collapse: collapse; width: 100%; text-align: center; margin-bottom: 20px;"><tr>`;
        mcqs.forEach((q, idx) => {
             let letter = "?";
             if (q.options) {
                 const matchIdx = q.options.findIndex(o => cleanOption(o).trim() === cleanOption(q.correctAnswer).trim());
                 if (matchIdx !== -1) letter = String.fromCharCode(65 + matchIdx);
             }
             keyContent += `<td style="padding: 5px;">${idx + 1}.${letter}</td>`;
             if ((idx + 1) % 10 === 0) keyContent += `</tr><tr>`;
        });
        keyContent += `</tr></table>`;
    }

    if (tfs.length > 0) {
        keyContent += `<p style="font-weight: bold;">PHẦN II. ĐÚNG/SAI</p>`;
        tfs.forEach((q, idx) => {
            keyContent += `<p>Câu ${idx + 1}: ${q.correctAnswer}</p>`;
        });
    }

    if (sas.length > 0) {
        keyContent += `<p style="font-weight: bold;">PHẦN III. TRẢ LỜI NGẮN / TỰ LUẬN</p>`;
        sas.forEach((q, idx) => {
            keyContent += `<p>Câu ${idx + 1}: ${q.correctAnswer}</p>`;
        });
    }

    keyContent += `</div>`;
    const fullContent = `<html><head><meta charset='utf-8'></head><body>${keyContent}</body></html>`;
    downloadDoc(fullContent, `Dap_An_${subject}_${grade}_${Date.now()}.doc`);
  };

  const downloadDoc = (content: string, filename: string) => {
    const blob = new Blob(['\ufeff', content], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadExcel = () => {
    const dataToExport = viewingQuiz ? attempts.filter(a => a.quizId === viewingQuiz.id) : attempts;
    if (dataToExport.length === 0) { alert("Chưa có dữ liệu."); return; }
    const headers = ["Mã đề", "Tên đề thi", "Tên học sinh", "Lớp", "Điểm số", "Thời gian nộp"];
    const rows = dataToExport.map(a => {
        const quizTitle = quizzes.find(q => q.id === a.quizId)?.title || a.quizId;
        return [`"${a.quizId}"`, `"${quizTitle}"`, `"${a.studentName}"`, `"${a.studentClass}"`, `${a.score}/${a.totalScore}`, `"${new Date(a.timestamp).toLocaleString()}"`].join(",");
    });
    const csvContent = "data:text/csv;charset=utf-8," + "\uFEFF" + [headers.join(","), ...rows].join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", viewingQuiz ? `ket_qua_${viewingQuiz.title}.csv` : "tat_ca_ket_qua.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const renderQuestionList = (questions: Question[]) => (
    <div className="space-y-6">
      {questions.map((q, idx) => (
        <div key={q.id} className="p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex justify-between items-start mb-2">
            <span className="font-bold text-blue-800">Câu {idx + 1} ({q.type === QuestionType.MULTIPLE_CHOICE ? 'TN' : q.type === QuestionType.TRUE_FALSE ? 'Đ/S' : 'TLN'})</span>
            <span className={`text-xs px-2 py-1 rounded ${q.difficulty === Difficulty.RECALL ? 'bg-green-100 text-green-800' : q.difficulty === Difficulty.UNDERSTAND ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800'}`}>
              {q.difficulty === Difficulty.RECALL ? 'Nhận biết' : q.difficulty === Difficulty.UNDERSTAND ? 'Thông hiểu' : 'Vận dụng'}
            </span>
          </div>
          <p className="mb-3 text-gray-800 font-medium">{q.text}</p>
          {q.type === QuestionType.MULTIPLE_CHOICE && q.options && (
            <div className="grid grid-cols-1 gap-2 ml-4">
              {q.options.map((opt, i) => {
                const isCorrect = cleanOption(opt).trim() === cleanOption(q.correctAnswer).trim();
                return (
                  <div key={i} className={`p-2 rounded border ${isCorrect ? 'bg-green-50 border-green-300' : 'bg-white border-gray-200'}`}>
                    <span className={`font-semibold mr-2 ${isCorrect ? 'text-green-700 font-bold underline' : ''}`}>
                      {String.fromCharCode(65 + i)}.
                    </span> 
                    {cleanOption(opt)}
                  </div>
                );
              })}
            </div>
          )}
          {q.type === QuestionType.TRUE_FALSE && q.options && (
              <div className="ml-4 space-y-3">
                <div className="bg-gray-50 p-3 rounded border border-gray-200">
                    <p className="text-sm font-bold text-gray-600 mb-2">Các mệnh đề:</p>
                    {q.options.map((opt, i) => {
                        const answers = q.correctAnswer.split(/[,|]/).map(s => s.trim());
                        const ans = answers[i] || "?";
                        const isTrue = ans.toLowerCase().includes('đúng') || ans.toLowerCase() === 'true';
                        return (
                            <div key={i} className="flex justify-between items-center py-2 border-b last:border-0">
                                <span className="flex-1"><span className="font-bold mr-2">{String.fromCharCode(97+i)})</span> {opt}</span>
                                <span className={`ml-4 px-2 py-0.5 rounded text-xs font-bold ${isTrue ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{ans}</span>
                            </div>
                        )
                    })}
                </div>
              </div>
          )}
          {q.explanation && (
            <div className="mt-2 p-3 bg-blue-50 border border-blue-100 rounded text-sm text-blue-900">
              <span className="font-bold text-blue-700">Lời giải: </span>{q.explanation}
            </div>
          )}
        </div>
      ))}
    </div>
  );

  const inputClass = "w-full rounded-md shadow-sm p-1.5 text-sm border border-blue-400 bg-blue-50 text-blue-900 focus:ring-2 focus:ring-blue-500 font-medium";
  const numberInputClass = "w-full mt-0.5 p-1.5 rounded-md text-sm border border-blue-400 bg-blue-50 text-blue-900 font-bold text-center";

  return (
    <div className="max-w-7xl mx-auto p-4">
