                  }} className="bg-gray-100 text-gray-700 px-3 py-2 rounded-lg font-bold text-sm">Xuất nháp</button>
                  <button onClick={handlePublish} className="bg-green-600 text-white px-5 py-2 rounded-lg font-bold">Lưu & Phát hành</button>
                </div>
              )}
            </div>
            {generatedQuestions.length === 0 ? <p className="text-gray-400 text-center py-20">Chưa có câu hỏi.</p> : renderQuestionList(generatedQuestions)}
          </div>
        </div>
      )}

      {activeTab === 'results' && (
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 min-h-[600px]">
           {viewingQuiz ? (
             <div>
               <div className="flex justify-between items-center mb-6 border-b pb-4">
                 <button onClick={() => setViewingQuiz(null)} className="p-2 bg-gray-100 rounded-full"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg></button>
                 <h2 className="text-xl font-bold">{viewingQuiz.title}</h2>
                 <div className="flex gap-2">
                   <button onClick={() => handleExport4Versions(viewingQuiz)} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold">Xuất 4 mã đề (Mix)</button>
                   <button onClick={() => handleExportAnswerKey4Versions(viewingQuiz)} className="bg-purple-600 text-white px-4 py-2 rounded-lg text-sm font-bold">Xuất Đáp án (4 Mã đề)</button>
                   <button onClick={downloadExcel} className="bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-bold">Xuất Excel</button>
                 </div>
               </div>
               <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                 <div><h3 className="text-lg font-semibold mb-4 border-b pb-2">Đề thi</h3><div className="max-h-[500px] overflow-y-auto">{renderQuestionList(viewingQuiz.questions)}</div></div>
                 <div><h3 className="text-lg font-semibold mb-4 border-b pb-2">Kết quả</h3><div className="overflow-x-auto"><table className="w-full text-left"><thead><tr className="bg-gray-100 text-xs"><th>Học sinh</th><th>Lớp</th><th className="text-center">Điểm</th></tr></thead><tbody>{attempts.filter(a => a.quizId === viewingQuiz.id).map(a => (<tr key={a.id} className="border-b"><td className="p-2">{a.studentName}</td><td className="p-2">{a.studentClass}</td><td className="p-2 text-center font-bold">{a.score}</td></tr>))}</tbody></table></div></div>
               </div>
             </div>
           ) : (
             <div>
               <h2 className="text-xl font-bold mb-6">Quản lý Đề thi</h2>
               <table className="w-full text-left border-collapse">
                 <thead><tr className="bg-blue-50 text-blue-800 text-xs uppercase"><th>Ngày tạo</th><th>Tên đề thi</th><th className="text-center">Lượt làm</th><th className="text-center">Trạng thái</th><th className="text-right">Thao tác</th></tr></thead>
                 <tbody>{quizzes.slice().reverse().map((quiz) => (
                   <tr key={quiz.id} className="border-b hover:bg-gray-50">
                     <td className="p-3 text-sm">{new Date(quiz.createdAt).toLocaleDateString()}</td>
                     <td className="p-3 font-medium">{quiz.title}</td>
                     <td className="p-3 text-center"><span className="bg-blue-100 px-2 py-1 rounded text-xs font-bold">{attempts.filter(a => a.quizId === quiz.id).length}</span></td>
                     <td className="p-3 text-center"><button onClick={() => handleToggleStatus(quiz.id, quiz.isActive)} className={`w-10 h-5 rounded-full relative ${quiz.isActive ? 'bg-green-500' : 'bg-gray-300'}`}><span className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${quiz.isActive ? 'right-1' : 'left-1'}`}></span></button></td>
                     <td className="p-3 text-right"><div className="flex justify-end gap-2"><button onClick={() => setViewingQuiz(quiz)} className="text-blue-600 p-1"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg></button><button onClick={() => handleDeleteQuiz(quiz.id)} className="text-red-500 p-1"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg></button></div></td>
                   </tr>
                 ))}</tbody>
               </table>
             </div>
           )}
        </div>
      )}
    </div>
  );
};

export default TeacherDashboard;

import { Quiz, StudentAttempt } from '../types';

const QUIZ_KEY = 'ai_quiz_app_quizzes';
const RESULT_KEY = 'ai_quiz_app_results';

export const saveQuiz = (quiz: Quiz): void => {
  const quizzes = getQuizzes();
  quizzes.push(quiz);
  localStorage.setItem(QUIZ_KEY, JSON.stringify(quizzes));
};

export const getQuizzes = (): Quiz[] => {
  const data = localStorage.getItem(QUIZ_KEY);
  return data ? JSON.parse(data) : [];
};

export const getQuizById = (id: string): Quiz | undefined => {
  const quizzes = getQuizzes();
  return quizzes.find(q => q.id === id);
};

export const deleteQuiz = (id: string): void => {
  // Xóa đề thi
  let quizzes = getQuizzes();
  quizzes = quizzes.filter(q => q.id !== id);
  localStorage.setItem(QUIZ_KEY, JSON.stringify(quizzes));

  // Xóa các kết quả làm bài liên quan
  let attempts = getAttempts();
  attempts = attempts.filter(a => a.quizId !== id);
  localStorage.setItem(RESULT_KEY, JSON.stringify(attempts));
};

export const updateQuizStatus = (id: string, isActive: boolean): void => {
  const quizzes = getQuizzes();
  const quiz = quizzes.find(q => q.id === id);
  if (quiz) {
    quiz.isActive = isActive;
    localStorage.setItem(QUIZ_KEY, JSON.stringify(quizzes));
  }
};

export const saveAttempt = (attempt: StudentAttempt): void => {
  const results = getAttempts();
  results.push(attempt);
  localStorage.setItem(RESULT_KEY, JSON.stringify(results));
};

export const getAttempts = (): StudentAttempt[] => {
  const data = localStorage.getItem(RESULT_KEY);
  return data ? JSON.parse(data) : [];
};

export const getAttemptsByStudent = (quizId: string, name: string, className: string): StudentAttempt[] => {
  const all = getAttempts();
  return all.filter(
    a => a.quizId === quizId && 
    a.studentName.toLowerCase() === name.toLowerCase() && 
    a.studentClass.toLowerCase() === className.toLowerCase()
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { SUBJECTS, GRADES, QuizConfig, QuestionType, Difficulty, Question, Quiz, StudentAttempt } from '../types';
import { generateQuizQuestions, MatrixInput, analyzeMatrixFromInput } from '../services/geminiService';
import { saveQuiz, getQuizzes, getAttempts, deleteQuiz, updateQuizStatus } from '../services/storageService';

// Declare types for global libraries
declare const mammoth: any;
declare const pdfjsLib: any;

const TeacherDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'create' | 'results'>('create');

  // Form State
  const [subject, setSubject] = useState(SUBJECTS[0]);
  const [grade, setGrade] = useState(GRADES[0]);
  const [lesson, setLesson] = useState('');

  const [mcCount, setMcCount] = useState(5);
  const [tfCount, setTfCount] = useState(0);
  const [saCount, setSaCount] = useState(0);

  const [mcPoints, setMcPoints] = useState(4.0);
  const [tfPoints, setTfPoints] = useState(2.0);
  const [saPoints, setSaPoints] = useState(1.0);

  const [recallCount, setRecallCount] = useState(3);
  const [understandCount, setUnderstandCount] = useState(2);
  const [applyCount, setApplyCount] = useState(0);
  const [advancedCount, setAdvancedCount] = useState(0);

  // File state
  const [matrixFile, setMatrixFile] = useState<{
    name: string;
    type: 'image' | 'text';
    data: string;
    mimeType?: string;
  } | null>(null);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedQuestions, setGeneratedQuestions] = useState<Question[]>([]);
  const [quizSaved, setQuizSaved] = useState(false);
  const [publishImmediately, setPublishImmediately] = useState(true);

  // Results & Viewing State
  const [attempts, setAttempts] = useState<StudentAttempt[]>([]);
  const [quizzes, setQuizzes] = useState<Quiz[]>([]);
  const [viewingQuiz, setViewingQuiz] = useState<Quiz | null>(null);

  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadData = () => {
    setAttempts(getAttempts());
    setQuizzes(getQuizzes());
  };

  useEffect(() => {
    if (activeTab === 'results') {
      loadData();
      setViewingQuiz(null);
    }
  }, [activeTab]);

  const processMatrixData = async (data: MatrixInput, fileName: string) => {
    if (data.type === 'image') {
      setMatrixFile({ name: fileName, type: 'image', data: data.data, mimeType: data.mimeType });
    } else {
      setMatrixFile({ name: fileName, type: 'text', data: data.content });
    }

    setIsAnalyzing(true);
    try {
      const result = await analyzeMatrixFromInput(data);
      setMcCount(result.counts[QuestionType.MULTIPLE_CHOICE]);
      setTfCount(result.counts[QuestionType.TRUE_FALSE]);
      setSaCount(result.counts[QuestionType.SHORT_ANSWER]);
      setRecallCount(result.difficulty[Difficulty.RECALL]);
      setUnderstandCount(result.difficulty[Difficulty.UNDERSTAND]);
      setApplyCount(result.difficulty[Difficulty.APPLY]);
      setAdvancedCount(result.difficulty[Difficulty.ADVANCED]);
    } catch (e) {
      console.error("Auto-fill failed", e);
    } finally {
      setIsAnalyzing(false);
      setIsProcessingFile(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessingFile(true);
    try {
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64String = reader.result as string;
          const matches = base64String.match(/^data:(.+);base64,(.+)$/);
          if (matches) {
            processMatrixData({ type: 'image', mimeType: matches[1], data: matches[2] }, file.name);
          } else {
            setIsProcessingFile(false);
          }
        };
        reader.readAsDataURL(file);
      } else if (file.name.endsWith('.docx')) {
        const reader = new FileReader();
        reader.onloadend = (event) => {
          const arrayBuffer = event.target?.result as ArrayBuffer;
          mammoth.extractRawText({ arrayBuffer: arrayBuffer })
            .then((result: any) => {
              processMatrixData({ type: 'text', content: result.value }, file.name);
            })
            .catch((err: any) => {
              console.error(err);
              alert("Lỗi đọc file Word.");
              setIsProcessingFile(false);
            });
        };
        reader.readAsArrayBuffer(file);
      } else if (file.type === 'application/pdf' || file.name.endsWith('.pdf')) {
        const reader = new FileReader();
        reader.onloadend = async (event) => {
          const arrayBuffer = event.target?.result as ArrayBuffer;
          try {
            const loadingTask = pdfjsLib.getDocument(arrayBuffer);
            const pdf = await loadingTask.promise;
            let fullText = "";
            for (let i = 1; i <= pdf.numPages; i++) {
                const page = await pdf.getPage(i);
                const textContent = await page.getTextContent();
                const pageText = textContent.items.map((item: any) => item.str).join(' ');
                fullText += `--- Trang ${i} ---\n${pageText}\n`;
            }
            processMatrixData({ type: 'text', content: fullText }, file.name);
          } catch (err) {
            console.error(err);
            alert("Lỗi đọc file PDF.");
            setIsProcessingFile(false);
          }
        };
        reader.readAsArrayBuffer(file);
      } else {
        alert("Định dạng file không hỗ trợ.");
        setIsProcessingFile(false);
      }
    } catch (e) {
      console.error(e);
      alert("Có lỗi xảy ra khi xử lý file.");
      setIsProcessingFile(false);
    }
  };

  const clearFile = () => {
    setMatrixFile(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleGenerate = async () => {
    if (!lesson) {
      alert("Vui lòng nhập tên bài học");
      return;
    }
    const totalQ = mcCount + tfCount + saCount;
    if (totalQ === 0) {
      alert("Vui lòng nhập số lượng câu hỏi.");
      return;
    }
    setIsGenerating(true);
    setQuizSaved(false);
    setGeneratedQuestions([]);
    const config: QuizConfig = {
      subject, grade, lesson,
      totalQuestions: {
        [QuestionType.MULTIPLE_CHOICE]: mcCount,
        [QuestionType.TRUE_FALSE]: tfCount,
        [QuestionType.SHORT_ANSWER]: saCount,
      },
      difficultyDistribution: {
        [Difficulty.RECALL]: recallCount,
        [Difficulty.UNDERSTAND]: understandCount,
        [Difficulty.APPLY]: applyCount,
        [Difficulty.ADVANCED]: advancedCount,
      },
      partPoints: {
        [QuestionType.MULTIPLE_CHOICE]: mcPoints,
        [QuestionType.TRUE_FALSE]: tfPoints,
        [QuestionType.SHORT_ANSWER]: saPoints,
      }
    };
    try {
      let matrixInput: MatrixInput | undefined = undefined;
      if (matrixFile) {
        if (matrixFile.type === 'image' && matrixFile.mimeType) {
          matrixInput = { type: 'image', data: matrixFile.data, mimeType: matrixFile.mimeType };
        } else if (matrixFile.type === 'text') {
          matrixInput = { type: 'text', content: matrixFile.data };
        }
      }
      const questions = await generateQuizQuestions(config, matrixInput);
      if (questions && questions.length > 0) {
          setGeneratedQuestions(questions);
          setTimeout(() => {
            previewRef.current?.scrollIntoView({ behavior: 'smooth' });
          }, 100);
      } else {
          alert("AI không trả về câu hỏi nào.");
      }
    } catch (error) {
      alert((error as Error).message);
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePublish = () => {
    if (generatedQuestions.length === 0) return;
    const newQuiz: Quiz = {
      id: `quiz_${Date.now()}`,
      title: `${subject} - ${grade} - ${lesson}`,
      config: {
        subject, grade, lesson,
        totalQuestions: {
            [QuestionType.MULTIPLE_CHOICE]: mcCount,
            [QuestionType.TRUE_FALSE]: tfCount,
            [QuestionType.SHORT_ANSWER]: saCount,
        },
        difficultyDistribution: {
            [Difficulty.RECALL]: recallCount,
            [Difficulty.UNDERSTAND]: understandCount,
            [Difficulty.APPLY]: applyCount,
            [Difficulty.ADVANCED]: advancedCount,
        },
        partPoints: {
            [QuestionType.MULTIPLE_CHOICE]: mcPoints,
            [QuestionType.TRUE_FALSE]: tfPoints,
            [QuestionType.SHORT_ANSWER]: saPoints,
        }
      },
      questions: generatedQuestions,
      createdAt: Date.now(),
      isActive: publishImmediately,
    };
    saveQuiz(newQuiz);
    setQuizSaved(true);
    alert("Đề thi đã được lưu thành công.");
  };

  const handleDeleteQuiz = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Bạn có chắc chắn muốn xóa đề thi này và toàn bộ kết quả liên quan?")) {
        // Xóa trong storage
        deleteQuiz(id);

        // Cập nhật state ngay lập tức để UI re-render
        setQuizzes(prev => prev.filter(q => q.id !== id));
        setAttempts(prev => prev.filter(a => a.quizId !== id));

        if (viewingQuiz?.id === id) {
          setViewingQuiz(null);
        }
    }
  };

  const handleToggleStatus = (id: string, currentStatus: boolean) => {
    updateQuizStatus(id, !currentStatus);
    loadData();
    if (viewingQuiz && viewingQuiz.id === id) {
        setViewingQuiz({...viewingQuiz, isActive: !currentStatus});
    }
  };

  const cleanOption = (str: string) => {
    return str.replace(/^[A-D]\.\s*/i, '').replace(/<[^>]*>?/gm, '');
  };

  const clean = (str: string) => str.replace(/<[^>]*>?/gm, '');

  const seededRandom = (seed: number) => {
    let state = seed % 2147483647;
    if (state <= 0) state += 2147483646;
    return () => {
      state = (state * 48271) % 2147483647;
      return (state - 1) / 2147483646;
    };
  };

  const shuffleArrayWithSeed = <T,>(array: T[], seed: number): T[] => {
    const rng = seededRandom(seed);
    const newArr = [...array];
    for (let i = newArr.length - 1; i > 0; i--) {
      const j = Math.floor(rng() * (i + 1));
      [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
    }
    return newArr;
  };

  const getNumericSeed = (id: string, version: number) => {
    let hash = 0;
    const str = id + version;
    for (let i = 0; i < str.length; i++) {
        hash = ((hash << 5) - hash) + str.charCodeAt(i);
        hash |= 0; 
    }
    return Math.abs(hash);
  };

  const mixQuiz = (quiz: Quiz, version: number) => {
    const seed = getNumericSeed(quiz.id, version);
    const mcqs = quiz.questions.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
    const tfs = quiz.questions.filter(q => q.type === QuestionType.TRUE_FALSE);
    const sas = quiz.questions.filter(q => q.type === QuestionType.SHORT_ANSWER);

    const shuffledMcqs = shuffleArrayWithSeed(mcqs, seed + 1).map(q => {
        if (!q.options) return q;
        const shuffledOptions = shuffleArrayWithSeed([...q.options], seed + 2);
        return { ...q, options: shuffledOptions };
    });

    const shuffledTfs = shuffleArrayWithSeed(tfs, seed + 3);
    const shuffledSas = shuffleArrayWithSeed(sas, seed + 4);

    return [...shuffledMcqs, ...shuffledTfs, ...shuffledSas];
  };

  const generateExamDocHtml = (quiz: Quiz, questionsData: Question[], quizCode: string, isPreview: boolean = false) => {
    const p1 = quiz.config.partPoints[QuestionType.MULTIPLE_CHOICE].toFixed(1).replace('.', ',');
    const p2 = quiz.config.partPoints[QuestionType.TRUE_FALSE].toFixed(1).replace('.', ',');
    const p3 = quiz.config.partPoints[QuestionType.SHORT_ANSWER].toFixed(1).replace('.', ',');

    const headerContent = `
      <div style="font-family: 'Times New Roman', serif;">
        <table style="width: 100%; border: none; margin-bottom: 20px;">
          <tr>
            <td style="text-align: center; vertical-align: top; width: 45%;">
              <p style="margin: 0; font-size: 11pt; font-weight: bold;">TRƯỜNG THPT LỘC BÌNH</p>
              <p style="margin: 5px 0 0 0; font-weight: bold; font-size: 11pt;">${isPreview ? 'BẢN XEM TRƯỚC' : 'ĐỀ CHÍNH THỨC'}</p>
              <p style="margin: 10px 0 0 0; font-size: 10pt; font-weight: bold;">Mã đề: ${quizCode}</p>
            </td>
            <td style="text-align: center; vertical-align: top;">
              <p style="margin: 0; font-weight: bold; font-size: 11pt; text-transform: uppercase;">KIỂM TRA CUỐI HỌC KÌ I LỚP 10 NĂM HỌC 2025 - 2026</p>
              <p style="margin: 0; font-weight: bold; font-size: 12pt;">MÔN: ${quiz.config.subject.toUpperCase()}</p>
              <p style="margin: 0; font-size: 11pt; font-style: italic;">Thời gian làm bài: 45 phút</p>
              <p style="margin: 0; font-size: 10pt;">Đề kiểm tra gồm có 02 trang, (${questionsData.length} câu hỏi)</p>
            </td>
          </tr>
        </table>
        <p style="margin-bottom: 20px; font-size: 11pt;">Họ, tên học sinh: ............................................................................ Lớp: .............................</p>
      </div>
    `;

    let examContent = `<div style="font-family: 'Times New Roman', serif; font-size: 12pt;">`;

    const mcqs = questionsData.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
    const tfs = questionsData.filter(q => q.type === QuestionType.TRUE_FALSE);
    const sas = questionsData.filter(q => q.type === QuestionType.SHORT_ANSWER);

    if (mcqs.length > 0) {
        examContent += `<p style="font-weight: bold; margin-top: 10px;">PHẦN I (${p1} điểm). Thí sinh trả lời từ câu 1 đến câu ${mcqs.length}. Mỗi câu hỏi thí sinh chỉ chọn 1 phương án.</p>`;
        mcqs.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 10px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            if (q.options) {
                examContent += `<table style="width: 100%; margin-top: 5px; margin-left: 10px;"><tr>`;
                q.options.forEach((opt, i) => {
                    const letter = String.fromCharCode(65 + i);
                    if (i > 0 && i % 2 === 0) examContent += `</tr><tr>`;
                    examContent += `<td style="padding: 2px 5px; width: 50%;"><strong>${letter}.</strong> ${cleanOption(opt)}</td>`;
                });
                examContent += `</tr></table>`;
            }
            examContent += `</div>`;
        });
    }

    if (tfs.length > 0) {
        examContent += `<p style="font-weight: bold; margin-top: 15px;">PHẦN II (${p2} điểm). Thí sinh trả lời từ câu 1 đến câu ${tfs.length}. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.</p>`;
        tfs.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 15px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            if (q.options) {
                q.options.forEach((opt, i) => {
                    const letter = String.fromCharCode(97 + i);
                    examContent += `<p style="margin: 2px 0 2px 20px;"><strong>${letter})</strong> ${clean(opt)}</p>`;
                });
            }
            examContent += `</div>`;
        });
    }

    if (sas.length > 0) {
        examContent += `<p style="font-weight: bold; margin-top: 15px;">PHẦN III (${p3} điểm). Thí sinh trả lời các câu hỏi sau.</p>`;
        sas.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 10px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            examContent += `<p style="margin-top: 5px; border-bottom: 1px dotted #000; height: 40px;"></p>`;
            examContent += `</div>`;
        });
    }

    examContent += `</div><p style="text-align: center; font-weight: bold; margin-top: 30px;">..............Hết.............</p>`;
    return `${headerContent}${examContent}`;
  };

  const handleExportWord = (quiz: Quiz, questionsData: Question[], quizCode: string = "101") => {
    const html = generateExamDocHtml(quiz, questionsData, quizCode);
    const fullContent = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
      <head><meta charset='utf-8'></head>
      <body>${html}</body>
      </html>
    `;
    downloadDoc(fullContent, `De_Thi_${quizCode}_${Date.now()}.doc`);
  };

  const handleExport4Versions = (quiz: Quiz) => {
    for (let v = 0; v < 4; v++) {
      const quizCode = (101 + v).toString();
      const mixedQuestions = mixQuiz(quiz, 101 + v);
      handleExportWord(quiz, mixedQuestions, quizCode);
    }
    alert("Đã xuất 4 mã đề (101-104) thành công.");
  };

  const handleExportAnswerKey4Versions = (quiz: Quiz) => {
    let fullHtml = `<div style="font-family: 'Times New Roman', serif; font-size: 12pt;">
        <h2 style="text-align: center; text-transform: uppercase; margin-bottom: 30px;">BẢNG ĐÁP ÁN TỔNG HỢP (4 MÃ ĐỀ)</h2>
    `;

    for (let v = 0; v < 4; v++) {
        const quizCode = (101 + v).toString();
        const mixedQuestions = mixQuiz(quiz, 101 + v);

        const mcqs = mixedQuestions.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
        const tfs = mixedQuestions.filter(q => q.type === QuestionType.TRUE_FALSE);
        const sas = mixedQuestions.filter(q => q.type === QuestionType.SHORT_ANSWER);

        fullHtml += `<div style="margin-top: 40px; border-top: 2px solid #000; padding-top: 20px; page-break-before: ${v > 0 ? 'always' : 'auto'};">`;
        fullHtml += `<h3 style="text-align: center; background-color: #f3f4f6; padding: 10px;">ĐÁP ÁN MÃ ĐỀ: ${quizCode}</h3>`;

        if (mcqs.length > 0) {
            fullHtml += `<p style="font-weight: bold; margin-top: 10px;">PHẦN I. TRẮC NGHIỆM</p>`;
            fullHtml += `<table border="1" style="border-collapse: collapse; width: 100%; text-align: center; margin-bottom: 20px;"><tr>`;
            mcqs.forEach((q, idx) => {
                 let letter = "N/A";
                 if (q.options) {
                     const matchIdx = q.options.findIndex(o => cleanOption(o).trim().toLowerCase() === cleanOption(q.correctAnswer).trim().toLowerCase());
                     if (matchIdx !== -1) letter = String.fromCharCode(65 + matchIdx);
                 }
                 fullHtml += `<td style="padding: 5px; width: 10%;"><b>${idx + 1}</b>.${letter}</td>`;
                 if ((idx + 1) % 10 === 0 && idx < mcqs.length - 1) fullHtml += `</tr><tr>`;
            });
            const remaining = (10 - (mcqs.length % 10)) % 10;
            if (remaining > 0) {
                for(let r=0; r<remaining; r++) fullHtml += `<td></td>`;
            }
            fullHtml += `</tr></table>`;
        }

        if (tfs.length > 0) {
            fullHtml += `<p style="font-weight: bold; margin-top: 10px;">PHẦN II. TRẮC NGHIỆM ĐÚNG/SAI</p>`;
            fullHtml += `<table border="1" style="border-collapse: collapse; width: 100%; margin-bottom: 20px;">`;
            fullHtml += `<tr style="background-color: #f9fafb;"><th>Câu</th><th>Ý a</th><th>Ý b</th><th>Ý c</th><th>Ý d</th></tr>`;
            tfs.forEach((q, idx) => {
                const ansParts = q.correctAnswer.split(/[,|]/).map(s => s.trim());
                fullHtml += `<tr>
                    <td style="text-align: center; font-weight: bold;">${idx + 1}</td>
                    <td style="text-align: center;">${ansParts[0] || '-'}</td>
                    <td style="text-align: center;">${ansParts[1] || '-'}</td>
                    <td style="text-align: center;">${ansParts[2] || '-'}</td>
                    <td style="text-align: center;">${ansParts[3] || '-'}</td>
                </tr>`;
            });
            fullHtml += `</table>`;
        }

        if (sas.length > 0) {
            fullHtml += `<p style="font-weight: bold; margin-top: 10px;">PHẦN III. TỰ LUẬN / TRẢ LỜI NGẮN</p>`;
            sas.forEach((q, idx) => {
                fullHtml += `<div style="margin-bottom: 8px; border-bottom: 1px dashed #ccc; padding-bottom: 5px;">
                    <b>Câu ${idx + 1}:</b> <span style="color: #2563eb;">${q.correctAnswer}</span>
                    <br/><i style="font-size: 10pt; color: #666;">Giải thích: ${clean(q.explanation || 'Không có')}</i>
                </div>`;
            });
        }

        fullHtml += `</div>`;
    }

    fullHtml += `</div>`;

    const fullContent = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
      <head><meta charset='utf-8'></head>
      <body>${fullHtml}</body>
      </html>
    `;
    downloadDoc(fullContent, `Dap_An_Tong_Hop_4_Ma_De_${Date.now()}.doc`);
  };

  const downloadDoc = (content: string, filename: string) => {
    const blob = new Blob(['\ufeff', content], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadExcel = () => {
    const dataToExport = viewingQuiz ? attempts.filter(a => a.quizId === viewingQuiz.id) : attempts;
    if (dataToExport.length === 0) { alert("Chưa có dữ liệu."); return; }
    const headers = ["Học sinh", "Lớp", "Điểm số"];
    const rows = dataToExport.map(a => [`"${a.studentName}"`, `"${a.studentClass}"`, `${a.score}/${a.totalScore}`].join(","));
    const csvContent = "data:text/csv;charset=utf-8," + "\uFEFF" + [headers.join(","), ...rows].join("\n");
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI(csvContent));
    link.setAttribute("download", `ket_qua.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const renderQuestionList = (questions: Question[]) => (
    <div className="space-y-6">
      {questions.map((q, idx) => (
        <div key={q.id} className="p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex justify-between items-start mb-2">
            <span className="font-bold text-blue-800">Câu {idx + 1} ({q.type === QuestionType.MULTIPLE_CHOICE ? 'TN' : q.type === QuestionType.TRUE_FALSE ? 'Đ/S' : 'TLN'})</span>
            <span className={`text-xs px-2 py-1 rounded ${q.difficulty === Difficulty.RECALL ? 'bg-green-100 text-green-800' : q.difficulty === Difficulty.UNDERSTAND ? 'bg-yellow-100 text-yellow-800' : q.difficulty === Difficulty.APPLY ? 'bg-orange-100 text-orange-800' : 'bg-red-100 text-red-800'}`}>
              {q.difficulty === Difficulty.RECALL ? 'Nhận biết' : q.difficulty === Difficulty.UNDERSTAND ? 'Thông hiểu' : q.difficulty === Difficulty.APPLY ? 'Vận dụng' : 'Vận dụng cao'}
            </span>
          </div>
          <p className="mb-3 text-gray-800 font-medium">{q.text}</p>
          {q.type === QuestionType.MULTIPLE_CHOICE && q.options && (
            <div className="grid grid-cols-1 gap-2 ml-4">
              {q.options.map((opt, i) => (
                <div key={i} className={`p-2 rounded border bg-white border-gray-200`}>
                  <span className="font-semibold mr-2">{String.fromCharCode(65 + i)}.</span> {cleanOption(opt)}
                </div>
              ))}
            </div>
          )}
        </div>
      ))}
    </div>
  );

  const inputClass = "w-full rounded-md shadow-sm p-1.5 text-sm border border-blue-400 bg-blue-50 text-blue-900 focus:ring-2 focus:ring-blue-500 font-medium";
  const numberInputClass = "w-full mt-0.5 p-1.5 rounded-md text-sm border border-blue-400 bg-blue-50 text-blue-900 font-bold text-center";

  return (
    <div className="max-w-7xl mx-auto p-4">
      <header className="mb-6 flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-800">Chế độ Giáo viên</h1>
        <div className="space-x-3">
          <button onClick={() => setActiveTab('create')} className={`px-3 py-1.5 rounded-lg font-medium text-sm transition ${activeTab === 'create' ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-700'}`}>Soạn đề thi</button>
          <button onClick={() => setActiveTab('results')} className={`px-3 py-1.5 rounded-lg font-medium text-sm transition ${activeTab === 'results' ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-700'}`}>Quản lý đề & Kết quả</button>
        </div>
      </header>

      {activeTab === 'create' && (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          <div className="lg:col-span-1 bg-white p-4 rounded-xl shadow-sm border border-gray-100 h-fit sticky top-4 order-1">
            <h2 className="text-base font-bold mb-3 text-gray-700 border-b pb-2">Cấu hình Đề thi</h2>
            <div className="space-y-3">
              <div className="grid grid-cols-2 gap-2">
                  <div><label className="block text-xs font-bold text-gray-700 mb-0.5">Môn học</label><select value={subject} onChange={(e) => setSubject(e.target.value)} className={inputClass}>{SUBJECTS.map(s => <option key={s} value={s}>{s}</option>)}</select></div>
                  <div><label className="block text-xs font-bold text-gray-700 mb-0.5">Khối lớp</label><select value={grade} onChange={(e) => setGrade(e.target.value)} className={inputClass}>{GRADES.map(g => <option key={g} value={g}>{g}</option>)}</select></div>
              </div>
              <div><label className="block text-xs font-bold text-gray-700 mb-0.5">Tên bài học</label><input type="text" value={lesson} onChange={(e) => setLesson(e.target.value)} placeholder="Ví dụ: Hàm số..." className={inputClass} /></div>

              <div className="p-3 bg-gray-50 rounded-lg border border-dashed border-blue-300 relative">
                <label className="block text-xs font-bold text-gray-700 mb-2">Tải lên Ma trận (Ảnh, Word, PDF)</label>
                {isProcessingFile && <div className="absolute inset-0 bg-white/90 flex flex-col items-center justify-center z-10 rounded-lg"><span className="text-xs text-blue-600 font-bold animate-pulse">Đang xử lý...</span></div>}
                {!matrixFile ? (
                  <div className="text-center">
                    <input type="file" accept="image/*,.docx,.pdf" ref={fileInputRef} onChange={handleFileUpload} className="hidden" id="matrix-upload" />
                    <label htmlFor="matrix-upload" className="cursor-pointer flex flex-col items-center gap-1 text-blue-600 hover:text-blue-800"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg><span className="text-xs font-medium">Chọn file</span></label>
                  </div>
                ) : (
                  <div className="relative p-2 bg-blue-50 rounded border border-blue-200">
                    <p className="text-[10px] font-bold truncate">{matrixFile.name}</p>
                    <button onClick={clearFile} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1"><svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg></button>
                  </div>
                )}
              </div>

              <div className="pt-2 border-t">
                <label className="block text-xs font-bold text-gray-600 mb-2">Số câu / Điểm từng phần</label>
                <div className="space-y-3">
                  <div className="flex items-end gap-2">
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Phần I (TN)</label><input type="number" value={mcCount} onChange={e => setMcCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Số điểm</label><input type="number" step="0.5" value={mcPoints} onChange={e => setMcPoints(parseFloat(e.target.value) || 0)} className={numberInputClass} /></div>
                  </div>
                  <div className="flex items-end gap-2">
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Phần II (Đ/S)</label><input type="number" value={tfCount} onChange={e => setTfCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Số điểm</label><input type="number" step="0.5" value={tfPoints} onChange={e => setTfPoints(parseFloat(e.target.value) || 0)} className={numberInputClass} /></div>
                  </div>
                  <div className="flex items-end gap-2">
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Phần III (TL)</label><input type="number" value={saCount} onChange={e => setSaCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Số điểm</label><input type="number" step="0.5" value={saPoints} onChange={e => setSaPoints(parseFloat(e.target.value) || 0)} className={numberInputClass} /></div>
                  </div>
                </div>
              </div>

              <div className="pt-2 border-t">
                <label className="block text-xs font-bold text-gray-600 mb-2">Mức độ nhận thức</label>
                <div className="grid grid-cols-2 gap-2">
                  <div><label className="text-[10px] text-gray-500 block">Nhận biết</label><input type="number" value={recallCount} onChange={e => setRecallCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                  <div><label className="text-[10px] text-gray-500 block">Thông hiểu</label><input type="number" value={understandCount} onChange={e => setUnderstandCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                  <div><label className="text-[10px] text-gray-500 block">Vận dụng</label><input type="number" value={applyCount} onChange={e => setApplyCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                  <div><label className="text-[10px] text-gray-500 block">Vận dụng cao</label><input type="number" value={advancedCount} onChange={e => setAdvancedCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                </div>
              </div>

              <button onClick={handleGenerate} disabled={isGenerating || isProcessingFile} className="w-full bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700 disabled:bg-blue-300 text-sm mt-2">
                {isGenerating ? "Đang tạo..." : "Tạo Đề Thi (AI)"}
              </button>
            </div>
          </div>

          <div ref={previewRef} className="lg:col-span-3 bg-white p-6 rounded-xl shadow-sm border border-gray-100 min-h-[500px] order-2">
            <div className="flex justify-between items-center mb-6 border-b pb-4 sticky top-0 bg-white z-10 pt-2">
              <h2 className="text-xl font-bold text-gray-800">Xem trước Đề thi</h2>
              {generatedQuestions.length > 0 && (
                <div className="flex gap-2">
                  <button onClick={() => {
                    const tempQuiz: Quiz = {
                      id: 'temp', title: lesson, questions: generatedQuestions, createdAt: Date.now(), isActive: true,
                      config: { subject, grade, lesson, totalQuestions: { [QuestionType.MULTIPLE_CHOICE]: mcCount, [QuestionType.TRUE_FALSE]: tfCount, [QuestionType.SHORT_ANSWER]: saCount }, difficultyDistribution: { [Difficulty.RECALL]: recallCount, [Difficulty.UNDERSTAND]: understandCount, [Difficulty.APPLY]: applyCount, [Difficulty.ADVANCED]: advancedCount }, partPoints: { [QuestionType.MULTIPLE_CHOICE]: mcPoints, [QuestionType.TRUE_FALSE]: tfPoints, [QuestionType.SHORT_ANSWER]: saPoints } }
                    };
                    handleExportWord(tempQuiz, generatedQuestions, "Preview");
                  }} className="bg-gray-100 text-gray-700 px-3 py-2 rounded-lg font-bold text-sm">Xuất nháp</button>
                  <button onClick={handlePublish} className="bg-green-600 text-white px-5 py-2 rounded-lg font-bold">Lưu & Phát hành</button>
                </div>
              )}
            </div>
            {generatedQuestions.length === 0 ? <p className="text-gray-400 text-center py-20">Chưa có câu hỏi.</p> : renderQuestionList(generatedQuestions)}
          </div>
        </div>
      )}

      {activeTab === 'results' && (
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 min-h-[600px]">
           {viewingQuiz ? (
             <div>
               <div className="flex justify-between items-center mb-6 border-b pb-4">
                 <button onClick={() => setViewingQuiz(null)} className="p-2 bg-gray-100 rounded-full"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg></button>
                 <h2 className="text-xl font-bold">{viewingQuiz.title}</h2>
                 <div className="flex gap-2">
                   <button onClick={() => handleExport4Versions(viewingQuiz)} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold">Xuất 4 mã đề (Mix)</button>
                   <button onClick={() => handleExportAnswerKey4Versions(viewingQuiz)} className="bg-purple-600 text-white px-4 py-2 rounded-lg text-sm font-bold">Xuất Đáp án (4 Mã đề)</button>
                   <button onClick={downloadExcel} className="bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-bold">Xuất Excel</button>
                 </div>
               </div>
               <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                 <div><h3 className="text-lg font-semibold mb-4 border-b pb-2">Đề thi</h3><div className="max-h-[500px] overflow-y-auto">{renderQuestionList(viewingQuiz.questions)}</div></div>
                 <div><h3 className="text-lg font-semibold mb-4 border-b pb-2">Kết quả</h3><div className="overflow-x-auto"><table className="w-full text-left"><thead><tr className="bg-gray-100 text-xs"><th>Học sinh</th><th>Lớp</th><th className="text-center">Điểm</th></tr></thead><tbody>{attempts.filter(a => a.quizId === viewingQuiz.id).map(a => (<tr key={a.id} className="border-b"><td className="p-2">{a.studentName}</td><td className="p-2">{a.studentClass}</td><td className="p-2 text-center font-bold">{a.score}</td></tr>))}</tbody></table></div></div>
               </div>
             </div>
           ) : (
             <div>
               <h2 className="text-xl font-bold mb-6">Quản lý Đề thi</h2>
               <table className="w-full text-left border-collapse">
                 <thead><tr className="bg-blue-50 text-blue-800 text-xs uppercase"><th>Ngày tạo</th><th>Tên đề thi</th><th className="text-center">Lượt làm</th><th className="text-center">Trạng thái</th><th className="text-right">Thao tác</th></tr></thead>
                 <tbody>{quizzes.slice().reverse().map((quiz) => (
                   <tr key={quiz.id} className="border-b hover:bg-gray-50">
                     <td className="p-3 text-sm">{new Date(quiz.createdAt).toLocaleDateString()}</td>
                     <td className="p-3 font-medium">{quiz.title}</td>
                     <td className="p-3 text-center"><span className="bg-blue-100 px-2 py-1 rounded text-xs font-bold">{attempts.filter(a => a.quizId === quiz.id).length}</span></td>
                     <td className="p-3 text-center"><button onClick={() => handleToggleStatus(quiz.id, quiz.isActive)} className={`w-10 h-5 rounded-full relative ${quiz.isActive ? 'bg-green-500' : 'bg-gray-300'}`}><span className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${quiz.isActive ? 'right-1' : 'left-1'}`}></span></button></td>
                     <td className="p-3 text-right"><div className="flex justify-end gap-2"><button onClick={() => setViewingQuiz(quiz)} className="text-blue-600 p-1"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg></button><button onClick={(e) => handleDeleteQuiz(e, quiz.id)} className="text-red-500 p-1 hover:text-red-700 transition"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg></button></div></td>
                   </tr>
                 ))}</tbody>
               </table>
             </div>
           )}
        </div>
      )}
    </div>
  );
};

export default TeacherDashboard;

export enum QuestionType {
  MULTIPLE_CHOICE = 'MULTIPLE_CHOICE',
  TRUE_FALSE = 'TRUE_FALSE',
  SHORT_ANSWER = 'SHORT_ANSWER',
}

export enum Difficulty {
  RECALL = 'RECALL',      // Nhận biết
  UNDERSTAND = 'UNDERSTAND', // Thông hiểu
  APPLY = 'APPLY',        // Vận dụng
  ADVANCED = 'ADVANCED',  // Vận dụng cao
}

export interface Question {
  id: string;
  text: string;
  type: QuestionType;
  options?: string[]; // For MC
  correctAnswer: string;
  difficulty: Difficulty;
  explanation?: string; // Lời giải chi tiết
}

export interface QuizConfig {
  subject: string;
  grade: string;
  lesson: string;
  examName: string; // Tên bài kiểm tra (VD: Kiểm tra cuối học kì I)
  duration: number; // Thời gian làm bài (phút)
  totalQuestions: {
    [QuestionType.MULTIPLE_CHOICE]: number;
    [QuestionType.TRUE_FALSE]: number;
    [QuestionType.SHORT_ANSWER]: number;
  };
  difficultyDistribution: {
    [Difficulty.RECALL]: number;
    [Difficulty.UNDERSTAND]: number;
    [Difficulty.APPLY]: number;
    [Difficulty.ADVANCED]: number;
  };
  partPoints: {
    [QuestionType.MULTIPLE_CHOICE]: number;
    [QuestionType.TRUE_FALSE]: number;
    [QuestionType.SHORT_ANSWER]: number;
  };
}

export interface Quiz {
  id: string;
  title: string;
  config: QuizConfig;
  questions: Question[];
  createdAt: number;
  isActive: boolean; // Controls if students can see the quiz
}

export interface StudentAttempt {
  id: string;
  quizId: string;
  studentName: string;
  studentClass: string;
  score: number;
  totalScore: number;
  answers: Record<string, string>; // questionId -> studentAnswer
  timestamp: number;
}

// Subjects specific to Vietnam High School Curriculum (2018)
export const SUBJECTS = [
  "Toán học",
  "Ngữ văn",
  "Vật lí",
  "Hóa học",
  "Sinh học",
  "Lịch sử",
  "Địa lí",
  "Giáo dục công dân",
  "Tin học",
  "Công nghệ",
  "Tiếng Anh",
  "Giáo dục kinh tế và pháp luật",
  "Hoạt động trải nghiệm",
  "Âm nhạc",
  "Mỹ thuật",
  "Giáo dục quốc phòng và an ninh"
];

export const GRADES = ["Lớp 10", "Lớp 11", "Lớp 12"];

import React, { useState, useEffect, useRef } from 'react';
import { SUBJECTS, GRADES, QuizConfig, QuestionType, Difficulty, Question, Quiz, StudentAttempt } from '../types';
import { generateQuizQuestions, MatrixInput, analyzeMatrixFromInput } from '../services/geminiService';
import { saveQuiz, getQuizzes, getAttempts, deleteQuiz, updateQuizStatus } from '../services/storageService';

// Declare types for global libraries
declare const mammoth: any;
declare const pdfjsLib: any;

const TeacherDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'create' | 'results'>('create');

  // Form State
  const [subject, setSubject] = useState(SUBJECTS[0]);
  const [grade, setGrade] = useState(GRADES[0]);
  const [lesson, setLesson] = useState('');
  const [examName, setExamName] = useState('KIỂM TRA CUỐI HỌC KÌ I');
  const [duration, setDuration] = useState(45);

  const [mcCount, setMcCount] = useState(5);
  const [tfCount, setTfCount] = useState(0);
  const [saCount, setSaCount] = useState(0);

  const [mcPoints, setMcPoints] = useState(4.0);
  const [tfPoints, setTfPoints] = useState(2.0);
  const [saPoints, setSaPoints] = useState(1.0);

  const [recallCount, setRecallCount] = useState(3);
  const [understandCount, setUnderstandCount] = useState(2);
  const [applyCount, setApplyCount] = useState(0);
  const [advancedCount, setAdvancedCount] = useState(0);

  // File state
  const [matrixFile, setMatrixFile] = useState<{
    name: string;
    type: 'image' | 'text';
    data: string;
    mimeType?: string;
  } | null>(null);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedQuestions, setGeneratedQuestions] = useState<Question[]>([]);
  const [quizSaved, setQuizSaved] = useState(false);
  const [publishImmediately, setPublishImmediately] = useState(true);

  // Results & Viewing State
  const [attempts, setAttempts] = useState<StudentAttempt[]>([]);
  const [quizzes, setQuizzes] = useState<Quiz[]>([]);
  const [viewingQuiz, setViewingQuiz] = useState<Quiz | null>(null);

  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadData = () => {
    setAttempts(getAttempts());
    setQuizzes(getQuizzes());
  };

  useEffect(() => {
    if (activeTab === 'results') {
      loadData();
      setViewingQuiz(null);
    }
  }, [activeTab]);

  const processMatrixData = async (data: MatrixInput, fileName: string) => {
    if (data.type === 'image') {
      setMatrixFile({ name: fileName, type: 'image', data: data.data, mimeType: data.mimeType });
    } else {
      setMatrixFile({ name: fileName, type: 'text', data: data.content });
    }

    setIsAnalyzing(true);
    try {
      const result = await analyzeMatrixFromInput(data);
      setMcCount(result.counts[QuestionType.MULTIPLE_CHOICE]);
      setTfCount(result.counts[QuestionType.TRUE_FALSE]);
      setSaCount(result.counts[QuestionType.SHORT_ANSWER]);
      setRecallCount(result.difficulty[Difficulty.RECALL]);
      setUnderstandCount(result.difficulty[Difficulty.UNDERSTAND]);
      setApplyCount(result.difficulty[Difficulty.APPLY]);
      setAdvancedCount(result.difficulty[Difficulty.ADVANCED]);
    } catch (e) {
      console.error("Auto-fill failed", e);
    } finally {
      setIsAnalyzing(false);
      setIsProcessingFile(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessingFile(true);
    try {
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64String = reader.result as string;
          const matches = base64String.match(/^data:(.+);base64,(.+)$/);
          if (matches) {
            processMatrixData({ type: 'image', mimeType: matches[1], data: matches[2] }, file.name);
          } else {
            setIsProcessingFile(false);
          }
        };
        reader.readAsDataURL(file);
      } else if (file.name.endsWith('.docx')) {
        const reader = new FileReader();
        reader.onloadend = (event) => {
          const arrayBuffer = event.target?.result as ArrayBuffer;
          mammoth.extractRawText({ arrayBuffer: arrayBuffer })
            .then((result: any) => {
              processMatrixData({ type: 'text', content: result.value }, file.name);
            })
            .catch((err: any) => {
              console.error(err);
              alert("Lỗi đọc file Word.");
              setIsProcessingFile(false);
            });
        };
        reader.readAsArrayBuffer(file);
      } else if (file.type === 'application/pdf' || file.name.endsWith('.pdf')) {
        const reader = new FileReader();
        reader.onloadend = async (event) => {
          const arrayBuffer = event.target?.result as ArrayBuffer;
          try {
            const loadingTask = pdfjsLib.getDocument(arrayBuffer);
            const pdf = await loadingTask.promise;
            let fullText = "";
            for (let i = 1; i <= pdf.numPages; i++) {
                const page = await pdf.getPage(i);
                const textContent = await page.getTextContent();
                const pageText = textContent.items.map((item: any) => item.str).join(' ');
                fullText += `--- Trang ${i} ---\n${pageText}\n`;
            }
            processMatrixData({ type: 'text', content: fullText }, file.name);
          } catch (err) {
            console.error(err);
            alert("Lỗi đọc file PDF.");
            setIsProcessingFile(false);
          }
        };
        reader.readAsArrayBuffer(file);
      } else {
        alert("Định dạng file không hỗ trợ.");
        setIsProcessingFile(false);
      }
    } catch (e) {
      console.error(e);
      alert("Có lỗi xảy ra khi xử lý file.");
      setIsProcessingFile(false);
    }
  };

  const clearFile = () => {
    setMatrixFile(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleGenerate = async () => {
    if (!lesson) {
      alert("Vui lòng nhập tên bài học");
      return;
    }
    const totalQ = mcCount + tfCount + saCount;
    if (totalQ === 0) {
      alert("Vui lòng nhập số lượng câu hỏi.");
      return;
    }
    setIsGenerating(true);
    setQuizSaved(false);
    setGeneratedQuestions([]);
    const config: QuizConfig = {
      subject, grade, lesson, examName, duration,
      totalQuestions: {
        [QuestionType.MULTIPLE_CHOICE]: mcCount,
        [QuestionType.TRUE_FALSE]: tfCount,
        [QuestionType.SHORT_ANSWER]: saCount,
      },
      difficultyDistribution: {
        [Difficulty.RECALL]: recallCount,
        [Difficulty.UNDERSTAND]: understandCount,
        [Difficulty.APPLY]: applyCount,
        [Difficulty.ADVANCED]: advancedCount,
      },
      partPoints: {
        [QuestionType.MULTIPLE_CHOICE]: mcPoints,
        [QuestionType.TRUE_FALSE]: tfPoints,
        [QuestionType.SHORT_ANSWER]: saPoints,
      }
    };
    try {
      let matrixInput: MatrixInput | undefined = undefined;
      if (matrixFile) {
        if (matrixFile.type === 'image' && matrixFile.mimeType) {
          matrixInput = { type: 'image', data: matrixFile.data, mimeType: matrixFile.mimeType };
        } else if (matrixFile.type === 'text') {
          matrixInput = { type: 'text', content: matrixFile.data };
        }
      }
      const questions = await generateQuizQuestions(config, matrixInput);
      if (questions && questions.length > 0) {
          setGeneratedQuestions(questions);
          setTimeout(() => {
            previewRef.current?.scrollIntoView({ behavior: 'smooth' });
          }, 100);
      } else {
          alert("AI không trả về câu hỏi nào.");
      }
    } catch (error) {
      alert((error as Error).message);
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePublish = () => {
    if (generatedQuestions.length === 0) return;
    const newQuiz: Quiz = {
      id: `quiz_${Date.now()}`,
      title: `${examName} - ${subject} - ${grade}`,
      config: {
        subject, grade, lesson, examName, duration,
        totalQuestions: {
            [QuestionType.MULTIPLE_CHOICE]: mcCount,
            [QuestionType.TRUE_FALSE]: tfCount,
            [QuestionType.SHORT_ANSWER]: saCount,
        },
        difficultyDistribution: {
            [Difficulty.RECALL]: recallCount,
            [Difficulty.UNDERSTAND]: understandCount,
            [Difficulty.APPLY]: applyCount,
            [Difficulty.ADVANCED]: advancedCount,
        },
        partPoints: {
            [QuestionType.MULTIPLE_CHOICE]: mcPoints,
            [QuestionType.TRUE_FALSE]: tfPoints,
            [QuestionType.SHORT_ANSWER]: saPoints,
        }
      },
      questions: generatedQuestions,
      createdAt: Date.now(),
      isActive: publishImmediately,
    };
    saveQuiz(newQuiz);
    setQuizSaved(true);
    alert("Đề thi đã được lưu thành công.");
  };

  const handleDeleteQuiz = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Bạn có chắc chắn muốn xóa đề thi này và toàn bộ kết quả liên quan?")) {
        deleteQuiz(id);
        setQuizzes(prev => prev.filter(q => q.id !== id));
        setAttempts(prev => prev.filter(a => a.quizId !== id));
        if (viewingQuiz?.id === id) setViewingQuiz(null);
    }
  };

  const handleToggleStatus = (id: string, currentStatus: boolean) => {
    updateQuizStatus(id, !currentStatus);
    loadData();
    if (viewingQuiz && viewingQuiz.id === id) {
        setViewingQuiz({...viewingQuiz, isActive: !currentStatus});
    }
  };

  const cleanOption = (str: string) => str.replace(/^[A-D]\.\s*/i, '').replace(/<[^>]*>?/gm, '');
  const clean = (str: string) => str.replace(/<[^>]*>?/gm, '');

  const seededRandom = (seed: number) => {
    let state = seed % 2147483647;
    if (state <= 0) state += 2147483646;
    return () => {
      state = (state * 48271) % 2147483647;
      return (state - 1) / 2147483646;
    };
  };

  const shuffleArrayWithSeed = <T,>(array: T[], seed: number): T[] => {
    const rng = seededRandom(seed);
    const newArr = [...array];
    for (let i = newArr.length - 1; i > 0; i--) {
      const j = Math.floor(rng() * (i + 1));
      [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
    }
    return newArr;
  };

  const getNumericSeed = (id: string, version: number) => {
    let hash = 0;
    const str = id + version;
    for (let i = 0; i < str.length; i++) {
        hash = ((hash << 5) - hash) + str.charCodeAt(i);
        hash |= 0; 
    }
    return Math.abs(hash);
  };

  const mixQuiz = (quiz: Quiz, version: number) => {
    const seed = getNumericSeed(quiz.id, version);
    const mcqs = quiz.questions.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
    const tfs = quiz.questions.filter(q => q.type === QuestionType.TRUE_FALSE);
    const sas = quiz.questions.filter(q => q.type === QuestionType.SHORT_ANSWER);

    const shuffledMcqs = shuffleArrayWithSeed(mcqs, seed + 1).map(q => {
        if (!q.options) return q;
        const shuffledOptions = shuffleArrayWithSeed([...q.options], seed + 2);
        return { ...q, options: shuffledOptions };
    });

    const shuffledTfs = shuffleArrayWithSeed(tfs, seed + 3);
    const shuffledSas = shuffleArrayWithSeed(sas, seed + 4);

    return [...shuffledMcqs, ...shuffledTfs, ...shuffledSas];
  };

  const generateExamDocHtml = (quiz: Quiz, questionsData: Question[], quizCode: string, isPreview: boolean = false) => {
    const p1 = quiz.config.partPoints[QuestionType.MULTIPLE_CHOICE].toFixed(1).replace('.', ',');
    const p2 = quiz.config.partPoints[QuestionType.TRUE_FALSE].toFixed(1).replace('.', ',');
    const p3 = quiz.config.partPoints[QuestionType.SHORT_ANSWER].toFixed(1).replace('.', ',');

    const headerContent = `
      <div style="font-family: 'Times New Roman', serif;">
        <table style="width: 100%; border: none; margin-bottom: 20px;">
          <tr>
            <td style="text-align: center; vertical-align: top; width: 45%;">
              <p style="margin: 0; font-size: 11pt; font-weight: bold;">TRƯỜNG THPT LỘC BÌNH</p>
              <p style="margin: 5px 0 0 0; font-weight: bold; font-size: 11pt;">${isPreview ? 'BẢN XEM TRƯỚC' : 'ĐỀ CHÍNH THỨC'}</p>
              <p style="margin: 10px 0 0 0; font-size: 10pt; font-weight: bold;">Mã đề: ${quizCode}</p>
            </td>
            <td style="text-align: center; vertical-align: top;">
              <p style="margin: 0; font-weight: bold; font-size: 11pt; text-transform: uppercase;">${quiz.config.examName || 'KIỂM TRA HỌC KÌ'}</p>
              <p style="margin: 0; font-weight: bold; font-size: 12pt;">MÔN: ${quiz.config.subject.toUpperCase()}</p>
              <p style="margin: 0; font-size: 11pt; font-style: italic;">Thời gian làm bài: ${quiz.config.duration || 45} phút</p>
              <p style="margin: 0; font-size: 10pt;">Đề kiểm tra gồm có 02 trang, (${questionsData.length} câu hỏi)</p>
            </td>
          </tr>
        </table>
        <p style="margin-bottom: 20px; font-size: 11pt;">Họ, tên học sinh: ............................................................................ Lớp: .............................</p>
      </div>
    `;

    let examContent = `<div style="font-family: 'Times New Roman', serif; font-size: 12pt;">`;

    const mcqs = questionsData.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
    const tfs = questionsData.filter(q => q.type === QuestionType.TRUE_FALSE);
    const sas = questionsData.filter(q => q.type === QuestionType.SHORT_ANSWER);

    if (mcqs.length > 0) {
        examContent += `<p style="font-weight: bold; margin-top: 10px;">PHẦN I (${p1} điểm). Thí sinh trả lời từ câu 1 đến câu ${mcqs.length}. Mỗi câu hỏi thí sinh chỉ chọn 1 phương án.</p>`;
        mcqs.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 10px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            if (q.options) {
                examContent += `<table style="width: 100%; margin-top: 5px; margin-left: 10px;"><tr>`;
                q.options.forEach((opt, i) => {
                    const letter = String.fromCharCode(65 + i);
                    if (i > 0 && i % 2 === 0) examContent += `</tr><tr>`;
                    examContent += `<td style="padding: 2px 5px; width: 50%;"><strong>${letter}.</strong> ${cleanOption(opt)}</td>`;
                });
                examContent += `</tr></table>`;
            }
            examContent += `</div>`;
        });
    }

    if (tfs.length > 0) {
        examContent += `<p style="font-weight: bold; margin-top: 15px;">PHẦN II (${p2} điểm). Thí sinh trả lời từ câu 1 đến câu ${tfs.length}. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.</p>`;
        tfs.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 15px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            if (q.options) {
                q.options.forEach((opt, i) => {
                    const letter = String.fromCharCode(97 + i);
                    examContent += `<p style="margin: 2px 0 2px 20px;"><strong>${letter})</strong> ${clean(opt)}</p>`;
                });
            }
            examContent += `</div>`;
        });
    }

    if (sas.length > 0) {
        examContent += `<p style="font-weight: bold; margin-top: 15px;">PHẦN III (${p3} điểm). Thí sinh trả lời các câu hỏi sau.</p>`;
        sas.forEach((q, idx) => {
            examContent += `<div style="margin-bottom: 10px;">`;
            examContent += `<p style="margin: 0;"><strong>Câu ${idx + 1}:</strong> ${clean(q.text)}</p>`;
            examContent += `<p style="margin-top: 5px; border-bottom: 1px dotted #000; height: 40px;"></p>`;
            examContent += `</div>`;
        });
    }

    examContent += `</div><p style="text-align: center; font-weight: bold; margin-top: 30px;">..............Hết.............</p>`;
    return `${headerContent}${examContent}`;
  };

  const handleExportWord = (quiz: Quiz, questionsData: Question[], quizCode: string = "101") => {
    const html = generateExamDocHtml(quiz, questionsData, quizCode);
    const fullContent = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
      <head><meta charset='utf-8'></head>
      <body>${html}</body>
      </html>
    `;
    downloadDoc(fullContent, `De_Thi_${quizCode}_${Date.now()}.doc`);
  };

  const handleExport4Versions = (quiz: Quiz) => {
    for (let v = 0; v < 4; v++) {
      const quizCode = (101 + v).toString();
      const mixedQuestions = mixQuiz(quiz, 101 + v);
      handleExportWord(quiz, mixedQuestions, quizCode);
    }
    alert("Đã xuất 4 mã đề (101-104) thành công.");
  };

  const handleExportAnswerKey4Versions = (quiz: Quiz) => {
    let fullHtml = `<div style="font-family: 'Times New Roman', serif; font-size: 12pt;">
        <h2 style="text-align: center; text-transform: uppercase; margin-bottom: 30px;">BẢNG ĐÁP ÁN TỔNG HỢP (4 MÃ ĐỀ)</h2>
    `;
    for (let v = 0; v < 4; v++) {
        const quizCode = (101 + v).toString();
        const mixedQuestions = mixQuiz(quiz, 101 + v);
        const mcqs = mixedQuestions.filter(q => q.type === QuestionType.MULTIPLE_CHOICE);
        const tfs = mixedQuestions.filter(q => q.type === QuestionType.TRUE_FALSE);
        const sas = mixedQuestions.filter(q => q.type === QuestionType.SHORT_ANSWER);
        fullHtml += `<div style="margin-top: 40px; border-top: 2px solid #000; padding-top: 20px; page-break-before: ${v > 0 ? 'always' : 'auto'};">`;
        fullHtml += `<h3 style="text-align: center; background-color: #f3f4f6; padding: 10px;">ĐÁP ÁN MÃ ĐỀ: ${quizCode}</h3>`;
        if (mcqs.length > 0) {
            fullHtml += `<p style="font-weight: bold; margin-top: 10px;">PHẦN I. TRẮC NGHIỆM</p><table border="1" style="border-collapse: collapse; width: 100%; text-align: center; margin-bottom: 20px;"><tr>`;
            mcqs.forEach((q, idx) => {
                 let letter = "N/A";
                 if (q.options) {
                     const matchIdx = q.options.findIndex(o => cleanOption(o).trim().toLowerCase() === cleanOption(q.correctAnswer).trim().toLowerCase());
                     if (matchIdx !== -1) letter = String.fromCharCode(65 + matchIdx);
                 }
                 fullHtml += `<td style="padding: 5px; width: 10%;"><b>${idx + 1}</b>.${letter}</td>`;
                 if ((idx + 1) % 10 === 0 && idx < mcqs.length - 1) fullHtml += `</tr><tr>`;
            });
            const remaining = (10 - (mcqs.length % 10)) % 10;
            if (remaining > 0) for(let r=0; r<remaining; r++) fullHtml += `<td></td>`;
            fullHtml += `</tr></table>`;
        }
        if (tfs.length > 0) {
            fullHtml += `<p style="font-weight: bold; margin-top: 10px;">PHẦN II. TRẮC NGHIỆM ĐÚNG/SAI</p><table border="1" style="border-collapse: collapse; width: 100%; margin-bottom: 20px;"><tr style="background-color: #f9fafb;"><th>Câu</th><th>Ý a</th><th>Ý b</th><th>Ý c</th><th>Ý d</th></tr>`;
            tfs.forEach((q, idx) => {
                const ansParts = q.correctAnswer.split(/[,|]/).map(s => s.trim());
                fullHtml += `<tr><td style="text-align: center; font-weight: bold;">${idx + 1}</td><td style="text-align: center;">${ansParts[0] || '-'}</td><td style="text-align: center;">${ansParts[1] || '-'}</td><td style="text-align: center;">${ansParts[2] || '-'}</td><td style="text-align: center;">${ansParts[3] || '-'}</td></tr>`;
            });
            fullHtml += `</table>`;
        }
        if (sas.length > 0) {
            fullHtml += `<p style="font-weight: bold; margin-top: 10px;">PHẦN III. TỰ LUẬN / TRẢ LỜI NGẮN</p>`;
            sas.forEach((q, idx) => {
                fullHtml += `<div style="margin-bottom: 8px; border-bottom: 1px dashed #ccc; padding-bottom: 5px;"><b>Câu ${idx + 1}:</b> <span style="color: #2563eb;">${q.correctAnswer}</span><br/><i style="font-size: 10pt; color: #666;">Giải thích: ${clean(q.explanation || 'Không có')}</i></div>`;
            });
        }
        fullHtml += `</div>`;
    }
    fullHtml += `</div>`;
    const fullContent = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'></head><body>${fullHtml}</body></html>`;
    downloadDoc(fullContent, `Dap_An_Tong_Hop_4_Ma_De_${Date.now()}.doc`);
  };

  const downloadDoc = (content: string, filename: string) => {
    const blob = new Blob(['\ufeff', content], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadExcel = () => {
    const dataToExport = viewingQuiz ? attempts.filter(a => a.quizId === viewingQuiz.id) : attempts;
    if (dataToExport.length === 0) { alert("Chưa có dữ liệu."); return; }
    const headers = ["Học sinh", "Lớp", "Điểm số"];
    const rows = dataToExport.map(a => [`"${a.studentName}"`, `"${a.studentClass}"`, `${a.score}/${a.totalScore}`].join(","));
    const csvContent = "data:text/csv;charset=utf-8," + "\uFEFF" + [headers.join(","), ...rows].join("\n");
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI(csvContent));
    link.setAttribute("download", `ket_qua.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const renderQuestionList = (questions: Question[]) => (
    <div className="space-y-6">
      {questions.map((q, idx) => (
        <div key={q.id} className="p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex justify-between items-start mb-2">
            <span className="font-bold text-blue-800">Câu {idx + 1} ({q.type === QuestionType.MULTIPLE_CHOICE ? 'TN' : q.type === QuestionType.TRUE_FALSE ? 'Đ/S' : 'TLN'})</span>
            <span className={`text-xs px-2 py-1 rounded ${q.difficulty === Difficulty.RECALL ? 'bg-green-100 text-green-800' : q.difficulty === Difficulty.UNDERSTAND ? 'bg-yellow-100 text-yellow-800' : q.difficulty === Difficulty.APPLY ? 'bg-orange-100 text-orange-800' : 'bg-red-100 text-red-800'}`}>
              {q.difficulty === Difficulty.RECALL ? 'Nhận biết' : q.difficulty === Difficulty.UNDERSTAND ? 'Thông hiểu' : q.difficulty === Difficulty.APPLY ? 'Vận dụng' : 'Vận dụng cao'}
            </span>
          </div>
          <p className="mb-3 text-gray-800 font-medium">{q.text}</p>
          {q.type === QuestionType.MULTIPLE_CHOICE && q.options && (
            <div className="grid grid-cols-1 gap-2 ml-4">
              {q.options.map((opt, i) => (
                <div key={i} className={`p-2 rounded border bg-white border-gray-200`}><span className="font-semibold mr-2">{String.fromCharCode(65 + i)}.</span> {cleanOption(opt)}</div>
              ))}
            </div>
          )}
        </div>
      ))}
    </div>
  );

  const inputClass = "w-full rounded-md shadow-sm p-1.5 text-sm border border-blue-400 bg-blue-50 text-blue-900 focus:ring-2 focus:ring-blue-500 font-medium";
  const numberInputClass = "w-full mt-0.5 p-1.5 rounded-md text-sm border border-blue-400 bg-blue-50 text-blue-900 font-bold text-center";

  return (
    <div className="max-w-7xl mx-auto p-4">
      <header className="mb-6 flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-800">Chế độ Giáo viên</h1>
        <div className="space-x-3">
          <button onClick={() => setActiveTab('create')} className={`px-3 py-1.5 rounded-lg font-medium text-sm transition ${activeTab === 'create' ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-700'}`}>Soạn đề thi</button>
          <button onClick={() => setActiveTab('results')} className={`px-3 py-1.5 rounded-lg font-medium text-sm transition ${activeTab === 'results' ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-700'}`}>Quản lý đề & Kết quả</button>
        </div>
      </header>

      {activeTab === 'create' && (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          <div className="lg:col-span-1 bg-white p-4 rounded-xl shadow-sm border border-gray-100 h-fit sticky top-4 order-1">
            <h2 className="text-base font-bold mb-3 text-gray-700 border-b pb-2">Cấu hình Đề thi</h2>
            <div className="space-y-3">
              <div><label className="block text-xs font-bold text-gray-700 mb-0.5">Tên bài kiểm tra</label><input type="text" value={examName} onChange={(e) => setExamName(e.target.value)} placeholder="VD: Kiểm tra cuối học kì I" className={inputClass} /></div>
              <div className="grid grid-cols-2 gap-2">
                  <div><label className="block text-xs font-bold text-gray-700 mb-0.5">Môn học</label><select value={subject} onChange={(e) => setSubject(e.target.value)} className={inputClass}>{SUBJECTS.map(s => <option key={s} value={s}>{s}</option>)}</select></div>
                  <div><label className="block text-xs font-bold text-gray-700 mb-0.5">Khối lớp</label><select value={grade} onChange={(e) => setGrade(e.target.value)} className={inputClass}>{GRADES.map(g => <option key={g} value={g}>{g}</option>)}</select></div>
              </div>
              <div className="grid grid-cols-2 gap-2">
                  <div><label className="block text-xs font-bold text-gray-700 mb-0.5">Tên bài học</label><input type="text" value={lesson} onChange={(e) => setLesson(e.target.value)} placeholder="Ví dụ: Hàm số..." className={inputClass} /></div>
                  <div><label className="block text-xs font-bold text-gray-700 mb-0.5">Thời gian (phút)</label><input type="number" value={duration} onChange={(e) => setDuration(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
              </div>

              <div className="p-3 bg-gray-50 rounded-lg border border-dashed border-blue-300 relative">
                <label className="block text-xs font-bold text-gray-700 mb-2">Tải lên Ma trận (Ảnh, Word, PDF)</label>
                {isProcessingFile && <div className="absolute inset-0 bg-white/90 flex flex-col items-center justify-center z-10 rounded-lg"><span className="text-xs text-blue-600 font-bold animate-pulse">Đang xử lý...</span></div>}
                {!matrixFile ? (
                  <div className="text-center">
                    <input type="file" accept="image/*,.docx,.pdf" ref={fileInputRef} onChange={handleFileUpload} className="hidden" id="matrix-upload" />
                    <label htmlFor="matrix-upload" className="cursor-pointer flex flex-col items-center gap-1 text-blue-600 hover:text-blue-800"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg><span className="text-xs font-medium">Chọn file</span></label>
                  </div>
                ) : (
                  <div className="relative p-2 bg-blue-50 rounded border border-blue-200"><p className="text-[10px] font-bold truncate">{matrixFile.name}</p><button onClick={clearFile} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1"><svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg></button></div>
                )}
              </div>

              <div className="pt-2 border-t">
                <label className="block text-xs font-bold text-gray-600 mb-2">Số câu / Điểm từng phần</label>
                <div className="space-y-3">
                  <div className="flex items-end gap-2">
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Phần I (TN)</label><input type="number" value={mcCount} onChange={e => setMcCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Số điểm</label><input type="number" step="0.5" value={mcPoints} onChange={e => setMcPoints(parseFloat(e.target.value) || 0)} className={numberInputClass} /></div>
                  </div>
                  <div className="flex items-end gap-2">
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Phần II (Đ/S)</label><input type="number" value={tfCount} onChange={e => setTfCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Số điểm</label><input type="number" step="0.5" value={tfPoints} onChange={e => setTfPoints(parseFloat(e.target.value) || 0)} className={numberInputClass} /></div>
                  </div>
                  <div className="flex items-end gap-2">
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Phần III (TL)</label><input type="number" value={saCount} onChange={e => setSaCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                    <div className="flex-1"><label className="text-[10px] text-gray-500 block text-center">Số điểm</label><input type="number" step="0.5" value={saPoints} onChange={e => setSaPoints(parseFloat(e.target.value) || 0)} className={numberInputClass} /></div>
                  </div>
                </div>
              </div>

              <div className="pt-2 border-t">
                <label className="block text-xs font-bold text-gray-600 mb-2">Mức độ nhận thức</label>
                <div className="grid grid-cols-2 gap-2">
                  <div><label className="text-[10px] text-gray-500 block">Nhận biết</label><input type="number" value={recallCount} onChange={e => setRecallCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                  <div><label className="text-[10px] text-gray-500 block">Thông hiểu</label><input type="number" value={understandCount} onChange={e => setUnderstandCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                  <div><label className="text-[10px] text-gray-500 block">Vận dụng</label><input type="number" value={applyCount} onChange={e => setApplyCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                  <div><label className="text-[10px] text-gray-500 block">Vận dụng cao</label><input type="number" value={advancedCount} onChange={e => setAdvancedCount(parseInt(e.target.value) || 0)} className={numberInputClass} /></div>
                </div>
              </div>

              <button onClick={handleGenerate} disabled={isGenerating || isProcessingFile} className="w-full bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700 disabled:bg-blue-300 text-sm mt-2">{isGenerating ? "Đang tạo..." : "Tạo Đề Thi (AI)"}</button>
            </div>
          </div>

          <div ref={previewRef} className="lg:col-span-3 bg-white p-6 rounded-xl shadow-sm border border-gray-100 min-h-[500px] order-2">
            <div className="flex justify-between items-center mb-6 border-b pb-4 sticky top-0 bg-white z-10 pt-2">
              <h2 className="text-xl font-bold text-gray-800">Xem trước Đề thi</h2>
              {generatedQuestions.length > 0 && (
                <div className="flex gap-2">
                  <button onClick={() => {
                    const tempQuiz: Quiz = {
                      id: 'temp', title: examName, questions: generatedQuestions, createdAt: Date.now(), isActive: true,
                      config: { subject, grade, lesson, examName, duration, totalQuestions: { [QuestionType.MULTIPLE_CHOICE]: mcCount, [QuestionType.TRUE_FALSE]: tfCount, [QuestionType.SHORT_ANSWER]: saCount }, difficultyDistribution: { [Difficulty.RECALL]: recallCount, [Difficulty.UNDERSTAND]: understandCount, [Difficulty.APPLY]: applyCount, [Difficulty.ADVANCED]: advancedCount }, partPoints: { [QuestionType.MULTIPLE_CHOICE]: mcPoints, [QuestionType.TRUE_FALSE]: tfPoints, [QuestionType.SHORT_ANSWER]: saPoints } }
                    };
                    handleExportWord(tempQuiz, generatedQuestions, "Preview");
                  }} className="bg-gray-100 text-gray-700 px-3 py-2 rounded-lg font-bold text-sm">Xuất nháp</button>
                  <button onClick={handlePublish} className="bg-green-600 text-white px-5 py-2 rounded-lg font-bold">Lưu & Phát hành</button>
                </div>
              )}
            </div>
            {generatedQuestions.length === 0 ? <p className="text-gray-400 text-center py-20">Chưa có câu hỏi.</p> : renderQuestionList(generatedQuestions)}
          </div>
        </div>
      )}

      {activeTab === 'results' && (
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 min-h-[600px]">
           {viewingQuiz ? (
             <div>
               <div className="flex justify-between items-center mb-6 border-b pb-4">
                 <button onClick={() => setViewingQuiz(null)} className="p-2 bg-gray-100 rounded-full"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg></button>
                 <h2 className="text-xl font-bold">{viewingQuiz.title}</h2>
                 <div className="flex gap-2">
                   <button onClick={() => handleExport4Versions(viewingQuiz)} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold">Xuất 4 mã đề (Mix)</button>
                   <button onClick={() => handleExportAnswerKey4Versions(viewingQuiz)} className="bg-purple-600 text-white px-4 py-2 rounded-lg text-sm font-bold">Xuất Đáp án (4 Mã đề)</button>
                   <button onClick={downloadExcel} className="bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-bold">Xuất Excel</button>
                 </div>
               </div>
               <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                 <div><h3 className="text-lg font-semibold mb-4 border-b pb-2">Đề thi</h3><div className="max-h-[500px] overflow-y-auto">{renderQuestionList(viewingQuiz.questions)}</div></div>
                 <div><h3 className="text-lg font-semibold mb-4 border-b pb-2">Kết quả</h3><div className="overflow-x-auto"><table className="w-full text-left"><thead><tr className="bg-gray-100 text-xs"><th>Học sinh</th><th>Lớp</th><th className="text-center">Điểm</th></tr></thead><tbody>{attempts.filter(a => a.quizId === viewingQuiz.id).map(a => (<tr key={a.id} className="border-b"><td className="p-2">{a.studentName}</td><td className="p-2">{a.studentClass}</td><td className="p-2 text-center font-bold">{a.score}</td></tr>))}</tbody></table></div></div>
               </div>
             </div>
           ) : (
             <div>
               <h2 className="text-xl font-bold mb-6">Quản lý Đề thi</h2>
               <table className="w-full text-left border-collapse">
                 <thead><tr className="bg-blue-50 text-blue-800 text-xs uppercase"><th>Ngày tạo</th><th>Tên đề thi</th><th className="text-center">Lượt làm</th><th className="text-center">Trạng thái</th><th className="text-right">Thao tác</th></tr></thead>
                 <tbody>{quizzes.slice().reverse().map((quiz) => (
                   <tr key={quiz.id} className="border-b hover:bg-gray-50">
                     <td className="p-3 text-sm">{new Date(quiz.createdAt).toLocaleDateString()}</td>
                     <td className="p-3 font-medium">{quiz.title}</td>
                     <td className="p-3 text-center"><span className="bg-blue-100 px-2 py-1 rounded text-xs font-bold">{attempts.filter(a => a.quizId === quiz.id).length}</span></td>
                     <td className="p-3 text-center"><button onClick={() => handleToggleStatus(quiz.id, quiz.isActive)} className={`w-10 h-5 rounded-full relative ${quiz.isActive ? 'bg-green-500' : 'bg-gray-300'}`}><span className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${quiz.isActive ? 'right-1' : 'left-1'}`}></span></button></td>
                     <td className="p-3 text-right"><div className="flex justify-end gap-2"><button onClick={() => setViewingQuiz(quiz)} className="text-blue-600 p-1"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg></button><button onClick={(e) => handleDeleteQuiz(e, quiz.id)} className="text-red-500 p-1 hover:text-red-700 transition"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg></button></div></td>
                   </tr>
                 ))}</tbody>
               </table>
             </div>
           )}
        </div>
      )}
    </div>
  );
};

export default TeacherDashboard;

import React, { useState, useEffect } from 'react';
import { Quiz, StudentAttempt, QuestionType } from '../types';
import { getQuizzes, getAttemptsByStudent, saveAttempt } from '../services/storageService';

const StudentDashboard: React.FC = () => {
  const [step, setStep] = useState<'login' | 'select' | 'quiz' | 'result'>('login');

  // Student Info
  const [name, setName] = useState('');
  const [className, setClassName] = useState('');

  // Data
  const [availableQuizzes, setAvailableQuizzes] = useState<Quiz[]>([]);
  const [selectedQuiz, setSelectedQuiz] = useState<Quiz | null>(null);

  // Quiz State
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [score, setScore] = useState(0);

  useEffect(() => {
    const allQuizzes = getQuizzes();
    setAvailableQuizzes(allQuizzes.filter(q => q.isActive).reverse());
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (name.trim() && className.trim()) setStep('select');
  };

  const handleSelectQuiz = (quiz: Quiz) => {
    const attempts = getAttemptsByStudent(quiz.id, name, className);
    if (attempts.length >= 2) {
      alert("Bạn đã làm quá giới hạn 2 lần cho đề này!");
      return;
    }
    setSelectedQuiz(quiz);
    setAnswers({});
    setStep('quiz');
  };

  const handleSubmit = () => {
    if (!selectedQuiz) return;
    if (!confirm("Bạn có chắc chắn muốn nộp bài không?")) return;

    let totalPoints = 0;
    selectedQuiz.questions.forEach(q => {
      const studentAns = (answers[q.id] || "").trim().toLowerCase();
      const correctAns = q.correctAnswer.trim().toLowerCase();

      if (q.type === QuestionType.MULTIPLE_CHOICE) {
        if (studentAns === correctAns) totalPoints += 1;
      } else if (q.type === QuestionType.TRUE_FALSE) {
        const subAnswersStudent = studentAns.split(',').map(s => s.trim());
        const subAnswersCorrect = correctAns.split(/[,|]/).map(s => s.trim().toLowerCase());
        let correctCount = 0;
        const max = Math.max(subAnswersStudent.length, subAnswersCorrect.length);
        for(let i=0; i<max; i++) {
            if (subAnswersStudent[i] && subAnswersCorrect[i] && subAnswersStudent[i] === subAnswersCorrect[i]) correctCount++;
        }
        if (correctCount === 1) totalPoints += 0.1;
        else if (correctCount === 2) totalPoints += 0.25;
        else if (correctCount === 3) totalPoints += 0.5;
        else if (correctCount === 4) totalPoints += 1.0;
      } else if (q.type === QuestionType.SHORT_ANSWER) {
        if (studentAns === correctAns) totalPoints += 1;
      }
    });

    setScore(Number(totalPoints.toFixed(2)));
    const attempt: StudentAttempt = {
      id: `att_${Date.now()}`,
      quizId: selectedQuiz.id,
      studentName: name,
      studentClass: className,
      score: Number(totalPoints.toFixed(2)),
      totalScore: selectedQuiz.questions.length,
      answers,
      timestamp: Date.now()
    };
    saveAttempt(attempt);
    setStep('result');
  };

  const handleTFChange = (qId: string, index: number, value: string) => {
    const currentStr = answers[qId] || ",,,"; 
    const parts = currentStr.split(',');
    while(parts.length < 4) parts.push('');
    parts[index] = value;
    setAnswers({ ...answers, [qId]: parts.join(',') });
  };

  const resetToSelect = () => {
    setSelectedQuiz(null);
    setStep('select');
  };

  if (step === 'login') {
    return (
      <div className="min-h-screen flex items-center justify-center p-4">
        <div className="bg-white p-8 rounded-2xl shadow-lg max-w-md w-full border border-gray-100">
          <h1 className="text-2xl font-bold text-center text-blue-600 mb-2">Cổng thi Trực tuyến</h1>
          <p className="text-center text-gray-500 mb-6">Vui lòng nhập thông tin để bắt đầu</p>
          <form onSubmit={handleLogin} className="space-y-4">
            <div><label className="block text-sm font-medium text-gray-700 mb-1">Họ và tên</label><input required type="text" value={name} onChange={e => setName(e.target.value)} className="w-full border p-3 rounded-lg outline-none bg-blue-50 border-blue-300 text-blue-900" placeholder="Nguyễn Văn A" /></div>
            <div><label className="block text-sm font-medium text-gray-700 mb-1">Lớp</label><input required type="text" value={className} onChange={e => setClassName(e.target.value)} className="w-full border p-3 rounded-lg outline-none bg-blue-50 border-blue-300 text-blue-900" placeholder="10A1" /></div>
            <button type="submit" className="w-full bg-blue-600 text-white py-3 rounded-lg font-bold hover:bg-blue-700 transition mt-4">Vào hệ thống</button>
          </form>
        </div>
      </div>
    );
  }

  if (step === 'select') {
    return (
      <div className="max-w-4xl mx-auto p-4">
        <header className="flex justify-between items-center mb-6">
          <div><h1 className="text-2xl font-bold text-gray-800">Danh sách Đề thi</h1><p className="text-gray-500">Xin chào, <span className="font-semibold text-blue-600">{name} - {className}</span></p></div>
          <button onClick={() => setStep('login')} className="text-gray-500 hover:text-red-500 text-sm">Đăng xuất</button>
        </header>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {availableQuizzes.length === 0 ? <p className="text-gray-500 col-span-2 text-center py-10">Hiện chưa có đề thi nào được phát hành.</p> : availableQuizzes.map(quiz => {
              const attempts = getAttemptsByStudent(quiz.id, name, className);
              const remaining = 2 - attempts.length;
              return (
                <div key={quiz.id} className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 hover:shadow-md transition">
                  <h3 className="text-lg font-bold text-gray-800 mb-2">{quiz.title}</h3>
                  <div className="flex justify-between text-sm text-gray-500 mb-2"><span>{quiz.questions.length} câu hỏi</span><span>Thời gian: {quiz.config.duration || 45} phút</span></div>
                  <div className="text-xs text-gray-400 mb-4">Lượt đã làm: {attempts.length}/2</div>
                  <button onClick={() => handleSelectQuiz(quiz)} disabled={remaining <= 0} className={`w-full py-2 rounded-lg font-medium ${remaining > 0 ? 'bg-blue-600 text-white hover:bg-blue-700' : 'bg-gray-300 text-gray-500 cursor-not-allowed'}`}>{remaining > 0 ? 'Làm bài' : 'Đã hết lượt'}</button>
                </div>
              );
            })
          }
        </div>
      </div>
    );
  }

  if (step === 'quiz' && selectedQuiz) {
    return (
      <div className="max-w-3xl mx-auto p-4 pb-20">
        <header className="sticky top-0 bg-gray-50/95 backdrop-blur z-10 py-4 border-b mb-6 flex justify-between items-center">
            <h2 className="text-lg font-bold truncate pr-4">{selectedQuiz.title}</h2>
            <div className="text-sm font-medium text-gray-500">Đã trả lời: <span className="text-blue-600">{Object.keys(answers).length}/{selectedQuiz.questions.length}</span></div>
        </header>
        <div className="space-y-8">
            {selectedQuiz.questions.map((q, idx) => (
                <div key={q.id} className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <p className="font-medium text-gray-800 mb-4 text-lg"><span className="font-bold text-blue-600 mr-2">Câu {idx + 1}:</span>{q.text}</p>
                    {q.type === QuestionType.MULTIPLE_CHOICE && q.options && (
                        <div className="space-y-2">{q.options.map(opt => (<label key={opt} className={`flex items-start p-3 rounded-lg border cursor-pointer transition ${answers[q.id] === opt ? 'bg-blue-50 border-blue-300' : 'hover:bg-gray-50 border-gray-200'}`}><input type="radio" name={q.id} value={opt} checked={answers[q.id] === opt} onChange={() => setAnswers({...answers, [q.id]: opt})} className="mt-1 mr-3" /><span className="text-gray-700">{opt}</span></label>))}</div>
                    )}
                    {q.type === QuestionType.TRUE_FALSE && q.options && (
                        <div className="space-y-3">
                            <p className="text-sm italic text-gray-500 mb-2">Chọn Đúng hoặc Sai:</p>
                            {q.options.map((opt, i) => {
                                const currentComp = answers[q.id] || ",,,";
                                const currentVal = currentComp.split(',')[i] || "";
                                return (<div key={i} className="flex flex-col sm:flex-row sm:items-center justify-between p-3 rounded-lg border hover:bg-gray-50"><div className="mb-2 sm:mb-0 text-gray-700"><span className="font-bold mr-2">{String.fromCharCode(97+i)})</span>{opt}</div><div className="flex gap-2 shrink-0"><label className={`cursor-pointer px-3 py-1 rounded border text-sm ${currentVal === 'Đúng' ? 'bg-blue-600 text-white' : 'bg-white text-gray-600'}`}><input type="radio" className="hidden" checked={currentVal === 'Đúng'} onChange={() => handleTFChange(q.id, i, 'Đúng')} />Đúng</label><label className={`cursor-pointer px-3 py-1 rounded border text-sm ${currentVal === 'Sai' ? 'bg-blue-600 text-white' : 'bg-white text-gray-600'}`}><input type="radio" className="hidden" checked={currentVal === 'Sai'} onChange={() => handleTFChange(q.id, i, 'Sai')} />Sai</label></div></div>);
                            })}
                        </div>
                    )}
                    {q.type === QuestionType.SHORT_ANSWER && (<input type="text" placeholder="Nhập câu trả lời..." value={answers[q.id] || ''} onChange={(e) => setAnswers({...answers, [q.id]: e.target.value})} className="w-full border p-3 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />)}
                </div>
            ))}
        </div>
        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white border-t flex justify-center"><button onClick={handleSubmit} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-bold text-lg hover:bg-blue-700 shadow-lg">Nộp Bài</button></div>
      </div>
    );
  }

  if (step === 'result' && selectedQuiz) {
    return (
        <div className="min-h-screen flex items-center justify-center p-4">
            <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md w-full text-center border border-gray-100">
                <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6"><svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg></div>
                <h2 className="text-2xl font-bold mb-2">Hoàn thành bài thi!</h2><p className="text-gray-500 mb-6">Kết quả của bạn đã được ghi nhận.</p>
                <div className="bg-gray-50 p-6 rounded-xl mb-8"><p className="text-sm text-gray-500 uppercase font-semibold mb-2">Tổng điểm</p><p className="text-5xl font-black text-blue-600">{score}</p></div>
                <button onClick={resetToSelect} className="w-full bg-gray-800 text-white py-3 rounded-lg font-bold hover:bg-gray-900 transition">Quay lại danh sách</button>
            </div>
        </div>
    );
  }
  return null;
};

