import { GoogleGenAI, Type } from "@google/genai";
import { QuizConfig, QuestionType, Difficulty, Question } from '../types';

const getClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export type MatrixInput = 
  | { type: 'image'; data: string; mimeType: string }
  | { type: 'text'; content: string };

export interface AnalyzedMatrix {
  counts: {
    [QuestionType.MULTIPLE_CHOICE]: number;
    [QuestionType.TRUE_FALSE]: number;
    [QuestionType.SHORT_ANSWER]: number;
  };
  difficulty: {
    [Difficulty.RECALL]: number;
    [Difficulty.UNDERSTAND]: number;
    [Difficulty.APPLY]: number;
    [Difficulty.ADVANCED]: number;
  };
}

export const analyzeMatrixFromInput = async (matrixInput: MatrixInput): Promise<AnalyzedMatrix> => {
  const ai = getClient();
  const parts: any[] = [];

  const promptText = `
    Bạn là một trợ lý AI chuyên về giáo dục Việt Nam.
    Nhiệm vụ: Phân tích nội dung Ma trận đề thi hoặc Bản đặc tả đề thi được cung cấp.

    Hãy trích xuất chính xác số lượng câu hỏi cho từng phần và mức độ:
    1. Trắc nghiệm nhiều lựa chọn (MULTIPLE_CHOICE).
    2. Trắc nghiệm Đúng/Sai (TRUE_FALSE).
    3. Tự luận / Trả lời ngắn (SHORT_ANSWER).
    4. Phân phối mức độ: Nhận biết (RECALL), Thông hiểu (UNDERSTAND), Vận dụng (APPLY), Vận dụng cao (ADVANCED).

    Lưu ý quan trọng: Nếu tài liệu chỉ ghi tỉ lệ %, hãy tự động quy đổi sang số câu dựa trên tổng điểm 10 (thông thường TN 0.25đ/câu).
  `;

  parts.push({ text: promptText });

  if (matrixInput.type === 'text') {
    parts.push({ text: `\n--- NỘI DUNG TÀI LIỆU ---\n${matrixInput.content}\n` });
  } else {
    parts.push({ inlineData: { mimeType: matrixInput.mimeType, data: matrixInput.data } });
  }

  const schema = {
    type: Type.OBJECT,
    properties: {
      counts: {
        type: Type.OBJECT,
        properties: {
          [QuestionType.MULTIPLE_CHOICE]: { type: Type.INTEGER },
          [QuestionType.TRUE_FALSE]: { type: Type.INTEGER },
          [QuestionType.SHORT_ANSWER]: { type: Type.INTEGER },
        },
        required: [QuestionType.MULTIPLE_CHOICE, QuestionType.TRUE_FALSE, QuestionType.SHORT_ANSWER]
      },
      difficulty: {
        type: Type.OBJECT,
        properties: {
          [Difficulty.RECALL]: { type: Type.INTEGER },
          [Difficulty.UNDERSTAND]: { type: Type.INTEGER },
          [Difficulty.APPLY]: { type: Type.INTEGER },
          [Difficulty.ADVANCED]: { type: Type.INTEGER },
        },
        required: [Difficulty.RECALL, Difficulty.UNDERSTAND, Difficulty.APPLY, Difficulty.ADVANCED]
      }
    },
    required: ["counts", "difficulty"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.1
      }
    });

    const text = response.text || "{}";
    return JSON.parse(text) as AnalyzedMatrix;
  } catch (error) {
    console.error("Error analyzing matrix:", error);
    return {
      counts: { MULTIPLE_CHOICE: 0, TRUE_FALSE: 0, SHORT_ANSWER: 0 },
      difficulty: { RECALL: 0, UNDERSTAND: 0, APPLY: 0, ADVANCED: 0 }
    };
  }
};

export const generateQuizQuestions = async (
  config: QuizConfig, 
  matrixInput?: MatrixInput
): Promise<Question[]> => {
  const ai = getClient();
  let parts: any[] = [];

  let promptText = `Bạn là chuyên gia soạn đề thi theo chương trình GDPT 2018 của Việt Nam.
  Hãy tạo đề thi "${config.examName}" cho môn "${config.subject}", "${config.grade}", bài học/chủ đề: "${config.lesson}".

  Yêu cầu về cấu trúc câu hỏi:
  - PHẦN I (Trắc nghiệm 4 lựa chọn): ${config.totalQuestions[QuestionType.MULTIPLE_CHOICE]} câu.
  - PHẦN II (Trắc nghiệm Đúng/Sai): ${config.totalQuestions[QuestionType.TRUE_FALSE]} câu (mỗi câu có 4 ý a, b, c, d).
  - PHẦN III (Trả lời ngắn): ${config.totalQuestions[QuestionType.SHORT_ANSWER]} câu.

  Yêu cầu về mức độ:
  - Nhận biết: ${config.difficultyDistribution[Difficulty.RECALL]} câu.
  - Thông hiểu: ${config.difficultyDistribution[Difficulty.UNDERSTAND]} câu.
  - Vận dụng: ${config.difficultyDistribution[Difficulty.APPLY]} câu.
  - Vận dụng cao: ${config.difficultyDistribution[Difficulty.ADVANCED]} câu.

  Lưu ý quan trọng:
  1. Với câu hỏi Đúng/Sai: Trường 'correctAnswer' phải là chuỗi các giá trị Đúng/Sai ngăn cách bằng dấu phẩy (VD: "Đúng, Sai, Đúng, Sai"). 'options' chứa 4 nội dung cho 4 ý a, b, c, d.
  2. Nội dung kiến thức phải bám sát chương trình học và chính xác 100%.
  3. Lời giải chi tiết (explanation) phải rõ ràng, dễ hiểu.
  `;

  if (matrixInput) {
    promptText += `\nĐẶC BIỆT: Hãy căn cứ vào nội dung Ma trận/Đặc tả sau đây để ra đề:`;
    if (matrixInput.type === 'text') {
        promptText += `\n--- NỘI DUNG MA TRẬN ---\n${matrixInput.content}\n`;
    }
  }

  const schema = {
    type: Type.OBJECT,
    properties: {
      questions: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            text: { type: Type.STRING },
            type: { type: Type.STRING, enum: [QuestionType.MULTIPLE_CHOICE, QuestionType.TRUE_FALSE, QuestionType.SHORT_ANSWER] },
            options: { type: Type.ARRAY, items: { type: Type.STRING } },
            correctAnswer: { type: Type.STRING },
            explanation: { type: Type.STRING },
            difficulty: { type: Type.STRING, enum: [Difficulty.RECALL, Difficulty.UNDERSTAND, Difficulty.APPLY, Difficulty.ADVANCED] }
          },
          required: ["text", "type", "correctAnswer", "difficulty", "explanation"],
        }
      }
    },
    required: ["questions"]
  };

  try {
    parts.push({ text: promptText });
    if (matrixInput && matrixInput.type === 'image') {
        parts.push({ inlineData: { mimeType: matrixInput.mimeType, data: matrixInput.data } });
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.7
      }
    });

    const text = response.text || "{\"questions\": []}";
    const parsedData = JSON.parse(text);
    const questionsArray = Array.isArray(parsedData.questions) ? parsedData.questions : [];

    return questionsArray.map((q: any, index: number) => ({
      id: `q_${Date.now()}_${index}`,
      text: q.text || "Câu hỏi không có nội dung",
      type: q.type as QuestionType,
      options: Array.isArray(q.options) ? q.options : [],
      correctAnswer: q.correctAnswer || "",
      difficulty: q.difficulty as Difficulty,
      explanation: q.explanation || "Chưa có lời giải chi tiết."
    }));
  } catch (error) {
    console.error("Error generating quiz:", error);
    throw new Error("Lỗi khi kết nối với AI để tạo câu hỏi. Vui lòng kiểm tra lại cấu hình hoặc thử lại sau.");
  }
};

